--
-- Name: koed_enforce_conversation_observation_immutability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.koed_enforce_conversation_observation_immutability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	redaction_source_id text := current_setting('koed.observation_redaction_source_id', true);
	redaction_source_column text := current_setting('koed.observation_redaction_source_column', true);
BEGIN
	IF NEW IS NOT DISTINCT FROM OLD THEN
		RETURN NEW;
	END IF;
	IF redaction_source_id IS DISTINCT FROM OLD."id"::text
		OR redaction_source_column NOT IN ('raw_json', 'raw_text', 'transport_chunk_text', 'source_path', 'metadata') THEN
		RAISE EXCEPTION 'conversation observations are immutable'
			USING ERRCODE = '55000';
	END IF;
	IF NOT EXISTS (
		SELECT 1 FROM "encrypted_field_payloads" efp
		WHERE efp."source_table" = 'conversation_item_observations'
			AND efp."source_id" = OLD."id"
			AND efp."source_column" = redaction_source_column
			AND efp."invalidated_at" IS NULL
	) THEN
		RAISE EXCEPTION 'conversation observation redaction requires an active encrypted companion'
			USING ERRCODE = '55000';
	END IF;
	IF redaction_source_column = 'raw_json' THEN
		IF NEW."raw_json" IS NOT DISTINCT FROM OLD."raw_json"
			OR NEW."raw_json" IS DISTINCT FROM jsonb_build_object(
				'contentEncrypted', true,
				'encryptedSourceTable', 'conversation_item_observations',
				'encryptedSourceColumn', 'raw_json'
			)
			OR (to_jsonb(NEW) - 'raw_json') IS DISTINCT FROM (to_jsonb(OLD) - 'raw_json') THEN
			RAISE EXCEPTION 'conversation observation redaction changed an unexpected column'
				USING ERRCODE = '55000';
		END IF;
	ELSIF redaction_source_column = 'raw_text' THEN
		IF NEW."raw_text" IS NOT DISTINCT FROM OLD."raw_text"
			OR NEW."raw_text" IS DISTINCT FROM '[koed encrypted conversation item]'
			OR (to_jsonb(NEW) - 'raw_text') IS DISTINCT FROM (to_jsonb(OLD) - 'raw_text') THEN
			RAISE EXCEPTION 'conversation observation redaction changed an unexpected column'
				USING ERRCODE = '55000';
		END IF;
	ELSIF redaction_source_column = 'transport_chunk_text' THEN
		IF NEW."transport_chunk_text" IS NOT DISTINCT FROM OLD."transport_chunk_text"
			OR NEW."transport_chunk_text" IS DISTINCT FROM '[koed encrypted conversation item]'
			OR (to_jsonb(NEW) - 'transport_chunk_text') IS DISTINCT FROM (to_jsonb(OLD) - 'transport_chunk_text') THEN
			RAISE EXCEPTION 'conversation observation redaction changed an unexpected column'
				USING ERRCODE = '55000';
		END IF;
	ELSIF redaction_source_column = 'source_path' THEN
		IF NEW."source_path" IS NOT DISTINCT FROM OLD."source_path"
			OR NEW."source_path" IS DISTINCT FROM '[koed encrypted conversation item]'
			OR (to_jsonb(NEW) - 'source_path') IS DISTINCT FROM (to_jsonb(OLD) - 'source_path') THEN
			RAISE EXCEPTION 'conversation observation redaction changed an unexpected column'
				USING ERRCODE = '55000';
		END IF;
	ELSE
		IF NEW."metadata" IS NOT DISTINCT FROM OLD."metadata"
			OR NEW."metadata" IS DISTINCT FROM jsonb_build_object(
				'contentEncrypted', true,
				'encryptedSourceTable', 'conversation_item_observations',
				'encryptedSourceColumn', 'metadata'
			)
			OR (to_jsonb(NEW) - 'metadata') IS DISTINCT FROM (to_jsonb(OLD) - 'metadata') THEN
			RAISE EXCEPTION 'conversation observation redaction changed an unexpected column'
				USING ERRCODE = '55000';
		END IF;
	END IF;
	RETURN NEW;
END;
$$;


--
-- Name: koed_enforce_conversation_observation_parent_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.koed_enforce_conversation_observation_parent_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	parent_key text;
	parent_session_id uuid;
BEGIN
	IF NEW."conversation_item_id" IS NULL THEN
		IF NEW."canonical_item_key" IS NOT NULL OR NEW."ingestion_status" <> 'identity_unresolved' THEN
			RAISE EXCEPTION 'unlinked conversation observation claims canonical identity'
				USING ERRCODE = '23514';
		END IF;
		IF NOT EXISTS (
			SELECT 1 FROM "sessions" s
			WHERE s."id" = NEW."session_id"
				AND s."owner_user_id" = NEW."owner_user_id"
				AND s."visibility" = NEW."visibility"
		) THEN
			RAISE EXCEPTION 'unlinked conversation observation session identity mismatch'
				USING ERRCODE = '23514';
		END IF;
		RETURN NEW;
	END IF;
	SELECT ci."canonical_item_key", ci."session_id"
	INTO parent_key, parent_session_id
	FROM "conversation_items" ci
	WHERE ci."id" = NEW."conversation_item_id"
		AND ci."owner_user_id" = NEW."owner_user_id"
		AND ci."visibility" = NEW."visibility";
	IF parent_key IS NULL OR parent_key <> NEW."canonical_item_key" THEN
		RAISE EXCEPTION 'conversation observation parent identity mismatch'
			USING ERRCODE = '23514';
	END IF;
	IF NEW."session_id" IS DISTINCT FROM parent_session_id THEN
		RAISE EXCEPTION 'conversation observation session identity mismatch'
			USING ERRCODE = '23514';
	END IF;
	RETURN NEW;
END;
$$;


--
-- Name: koed_enforce_immutable_source_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.koed_enforce_immutable_source_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'logical_memories' THEN
    IF NEW.id IS DISTINCT FROM OLD.id OR
       NEW.owner_principal_id IS DISTINCT FROM OLD.owner_principal_id OR
       NEW.source_kind IS DISTINCT FROM OLD.source_kind OR
       NEW.logical_key IS DISTINCT FROM OLD.logical_key THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'logical_memory_identity_immutable_check',
        MESSAGE = 'Logical Memory source identity is immutable';
    END IF;
  ELSIF TG_TABLE_NAME = 'captured_session_logical_memories' THEN
    IF NEW.logical_memory_id IS DISTINCT FROM OLD.logical_memory_id OR
       NEW.owner_principal_id IS DISTINCT FROM OLD.owner_principal_id OR
       NEW.source_kind IS DISTINCT FROM OLD.source_kind OR
       NEW.source_session_id IS DISTINCT FROM OLD.source_session_id THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'captured_session_source_binding_immutable_check',
        MESSAGE = 'Captured Session source binding is immutable';
    END IF;
  ELSIF TG_TABLE_NAME = 'personal_note_logical_memories' THEN
    IF NEW.logical_memory_id IS DISTINCT FROM OLD.logical_memory_id OR
       NEW.owner_principal_id IS DISTINCT FROM OLD.owner_principal_id OR
       NEW.source_kind IS DISTINCT FROM OLD.source_kind OR
       NEW.source_note_id IS DISTINCT FROM OLD.source_note_id THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'personal_note_source_binding_immutable_check',
        MESSAGE = 'Personal Note source binding is immutable';
    END IF;
  ELSIF TG_TABLE_NAME = 'logical_memory_source_revisions' THEN
    IF NEW.id IS DISTINCT FROM OLD.id OR
       NEW.logical_memory_id IS DISTINCT FROM OLD.logical_memory_id OR
       NEW.owner_principal_id IS DISTINCT FROM OLD.owner_principal_id OR
       NEW.source_kind IS DISTINCT FROM OLD.source_kind OR
       NEW.revision IS DISTINCT FROM OLD.revision OR
       NEW.binding_hash IS DISTINCT FROM OLD.binding_hash THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'logical_memory_source_revision_immutable_check',
        MESSAGE = 'Logical Memory source revision identity is immutable';
    END IF;
  ELSIF TG_TABLE_NAME = 'captured_session_source_revisions' THEN
    IF NEW.source_revision_id IS DISTINCT FROM OLD.source_revision_id OR
       NEW.logical_memory_id IS DISTINCT FROM OLD.logical_memory_id OR
       NEW.owner_principal_id IS DISTINCT FROM OLD.owner_principal_id OR
       NEW.source_kind IS DISTINCT FROM OLD.source_kind OR
       NEW.revision IS DISTINCT FROM OLD.revision OR
       NEW.source_session_id IS DISTINCT FROM OLD.source_session_id OR
       NEW.source_cursor IS DISTINCT FROM OLD.source_cursor THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'captured_session_source_revision_immutable_check',
        MESSAGE = 'Captured Session source revision binding is immutable';
    END IF;
  ELSIF TG_TABLE_NAME = 'personal_note_source_revisions' THEN
    IF NEW.source_revision_id IS DISTINCT FROM OLD.source_revision_id OR
       NEW.logical_memory_id IS DISTINCT FROM OLD.logical_memory_id OR
       NEW.owner_principal_id IS DISTINCT FROM OLD.owner_principal_id OR
       NEW.source_kind IS DISTINCT FROM OLD.source_kind OR
       NEW.revision IS DISTINCT FROM OLD.revision OR
       NEW.source_note_id IS DISTINCT FROM OLD.source_note_id OR
       NEW.source_memory_event_id IS DISTINCT FROM OLD.source_memory_event_id THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'personal_note_source_revision_immutable_check',
        MESSAGE = 'Personal Note source revision binding is immutable';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: koed_enforce_memory_embedding_source_eligibility(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.koed_enforce_memory_embedding_source_eligibility() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
	IF NEW."message_id" IS NOT NULL AND EXISTS (
		SELECT 1
		FROM "messages" m
		WHERE m."id" = NEW."message_id"
			AND m."recall_eligible" = false
	) THEN
		RAISE EXCEPTION 'display-only messages cannot be embedded for recall'
			USING ERRCODE = '23514';
	END IF;
	IF NEW."memory_event_id" IS NOT NULL AND EXISTS (
		SELECT 1
		FROM "memory_events" me
		WHERE me."id" = NEW."memory_event_id"
			AND me."include_in_embedding" = false
	) THEN
		RAISE EXCEPTION 'embedding-ineligible Memory Events cannot be embedded'
			USING ERRCODE = '23514';
	END IF;
	RETURN NEW;
END;
$$;


--
-- Name: koed_validate_collaboration_participant_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.koed_validate_collaboration_participant_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    PERFORM koed_assert_collaboration_participant_set(OLD.thread_id);
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE')
     AND (TG_OP <> 'UPDATE' OR NEW.thread_id IS DISTINCT FROM OLD.thread_id) THEN
    PERFORM koed_assert_collaboration_participant_set(NEW.thread_id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: koed_validate_collaboration_thread_participants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.koed_validate_collaboration_thread_participants() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM koed_assert_collaboration_participant_set(OLD.id);
  ELSE
    PERFORM koed_assert_collaboration_participant_set(NEW.id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: notify_koed_graph_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_koed_graph_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  payload jsonb;
  row_id uuid;
  owner_id uuid;
  visibility_value text;
  project_id_value text;
  thread_id_value text;
  row_session_id uuid;
BEGIN
  IF tg_table_name = 'memory_node_sources' THEN
    row_id := CASE
      WHEN tg_op = 'DELETE' THEN old.memory_node_id
      ELSE new.memory_node_id
    END;

    SELECT mn.owner_user_id, mn.visibility::text
    INTO owner_id, visibility_value
    FROM memory_nodes mn
    WHERE mn.id = row_id;
  ELSIF tg_table_name = 'memory_embeddings' THEN
    row_id := CASE
      WHEN tg_op = 'DELETE' THEN old.memory_node_id
      ELSE new.memory_node_id
    END;
    owner_id := CASE
      WHEN tg_op = 'DELETE' THEN old.owner_user_id
      ELSE new.owner_user_id
    END;
    visibility_value := CASE
      WHEN tg_op = 'DELETE' THEN old.visibility::text
      ELSE new.visibility::text
    END;

    IF owner_id IS NULL AND row_id IS NOT NULL THEN
      SELECT mn.owner_user_id, mn.visibility::text
      INTO owner_id, visibility_value
      FROM memory_nodes mn
      WHERE mn.id = row_id;
    END IF;
  ELSIF tg_op = 'DELETE' THEN
    row_id := old.id;
    owner_id := old.owner_user_id;
    visibility_value := old.visibility::text;

    IF tg_table_name IN ('memory_events', 'messages', 'tool_events') THEN
      row_session_id := old.session_id;
    END IF;

    IF tg_table_name = 'memory_events' THEN
      project_id_value := old.payload ->> 'projectId';
      thread_id_value := old.payload #>> '{metadata,externalSessionId}';
    END IF;
  ELSE
    row_id := new.id;
    owner_id := new.owner_user_id;
    visibility_value := new.visibility::text;

    IF tg_table_name IN ('memory_events', 'messages', 'tool_events') THEN
      row_session_id := new.session_id;
    END IF;

    IF tg_table_name = 'memory_events' THEN
      project_id_value := new.payload ->> 'projectId';
      thread_id_value := new.payload #>> '{metadata,externalSessionId}';
    END IF;
  END IF;

  IF tg_table_name IN ('memory_events', 'messages', 'tool_events')
    AND (project_id_value IS NULL OR thread_id_value IS NULL)
  THEN
    SELECT
      coalesce(
        project_id_value,
        s.project_override_id,
        s.automatic_project_id,
        s.metadata ->> 'projectId',
        s.cwd
      ),
      coalesce(
        thread_id_value,
        s.metadata ->> 'externalSessionId',
        s.external_session_id,
        s.id::text
      )
    INTO project_id_value, thread_id_value
    FROM sessions s
    WHERE s.id = row_session_id;
  END IF;

  payload := jsonb_build_object(
    'table', tg_table_name,
    'operation', tg_op,
    'id', row_id,
    'ownerUserId', owner_id,
    'visibility', visibility_value,
    'changedAt', now()
  );

  IF tg_table_name IN ('memory_events', 'messages', 'tool_events') THEN
    payload := payload || jsonb_build_object(
      'projectId', project_id_value,
      'threadId', thread_id_value
    );
  END IF;

  PERFORM pg_notify('koed_graph_updates', payload::text);

  IF tg_op = 'DELETE' THEN
    RETURN old;
  END IF;
  RETURN new;
END;
$$;


--
-- Name: notify_koed_projection_work(); Type: FUNCTION; Schema: public; Owner: -
