--
-- Name: pds_guard_checkpoint_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pds_guard_checkpoint_records() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected_id text;
BEGIN
  expected_id := current_setting('koed.pds_replica_append_id', true);
  IF TG_TABLE_NAME = 'pds_replica_checkpoints' THEN
    IF TG_OP = 'INSERT' THEN
      IF expected_id IS DISTINCT FROM NEW.replica_id::text THEN
        RAISE EXCEPTION 'PDS checkpoint ledger writes require the trusted receiver';
      END IF;
      RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'PDS checkpoint ledger is immutable';
  END IF;
  IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.replica_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM pds_logical_replicas r
      WHERE r.id = NEW.replica_id AND r.materialization_profile = 'cumulative_checkpoint'
    ) AND expected_id IS DISTINCT FROM NEW.replica_id::text THEN
      RAISE EXCEPTION 'PDS replica item mappings require the trusted receiver';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.replica_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM pds_logical_replicas r
    WHERE r.id = OLD.replica_id AND r.materialization_profile = 'cumulative_checkpoint'
  ) THEN
    RAISE EXCEPTION 'PDS replica item mappings are immutable';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: pds_guard_checkpoint_replica(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pds_guard_checkpoint_replica() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected_id text;
BEGIN
  expected_id := current_setting('koed.pds_replica_append_id', true);
  IF TG_OP = 'INSERT' THEN
    IF NEW.materialization_profile = 'cumulative_checkpoint'
      AND (expected_id IS DISTINCT FROM NEW.id::text OR (NEW.checkpoint_ordinal <> '0' AND NOT (NEW.source_profile_epoch=1 AND current_setting('koed.pds_profile_baseline_ordinal',true) IS NOT DISTINCT FROM NEW.checkpoint_ordinal))) THEN
      RAISE EXCEPTION 'PDS checkpoint replicas must start through the trusted receiver';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.materialization_profile = 'cumulative_checkpoint' THEN
    IF NEW.group_id IS DISTINCT FROM OLD.group_id
      OR NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id
      OR NEW.materialization_profile IS DISTINCT FROM OLD.materialization_profile
      OR NEW.source_fingerprint IS DISTINCT FROM OLD.source_fingerprint
      OR NEW.local_session_id IS DISTINCT FROM OLD.local_session_id THEN
      RAISE EXCEPTION 'PDS checkpoint replica identity is immutable';
    END IF;
    IF NEW.source_profile_epoch IS DISTINCT FROM OLD.source_profile_epoch
      OR NEW.closure_hash IS DISTINCT FROM OLD.closure_hash
      OR NEW.checkpoint_ordinal IS DISTINCT FROM OLD.checkpoint_ordinal
      OR NEW.checkpoint_item_count IS DISTINCT FROM OLD.checkpoint_item_count THEN
      IF expected_id IS DISTINCT FROM OLD.id::text
        OR NOT (
          (NEW.source_profile_epoch=OLD.source_profile_epoch
            AND NEW.checkpoint_ordinal::numeric=OLD.checkpoint_ordinal::numeric+1
            AND NEW.checkpoint_item_count::numeric>OLD.checkpoint_item_count::numeric)
          OR (OLD.source_profile_epoch=0 AND NEW.source_profile_epoch=1
            AND current_setting('koed.pds_profile_baseline_ordinal',true) IS NOT DISTINCT FROM NEW.checkpoint_ordinal
            AND NEW.checkpoint_ordinal::numeric>OLD.checkpoint_ordinal::numeric
            AND NEW.checkpoint_item_count::numeric>=OLD.checkpoint_item_count::numeric)
        ) THEN
        RAISE EXCEPTION 'PDS checkpoint head advances only through a contiguous append';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: pds_guard_outbox_supersession(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pds_guard_outbox_supersession() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.state='superseded' THEN
      RAISE EXCEPTION 'PDS outbox supersession requires an existing publication';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.state='superseded' AND
    (to_jsonb(NEW)-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'updated_at') THEN
    RAISE EXCEPTION 'PDS superseded publication history is immutable';
  END IF;
  IF NEW.state='superseded' AND OLD.state<>'superseded' THEN
    IF OLD.state='acked' OR NEW.superseded_from_state IS DISTINCT FROM OLD.state
      OR NEW.lease_owner IS NOT NULL OR NEW.lease_until IS NOT NULL
      OR NOT EXISTS (
        SELECT 1 FROM pds_session_closures old_source
        JOIN pds_session_closures replacement
          ON replacement.group_id=old_source.group_id
          AND replacement.source_session_id=old_source.source_session_id
        WHERE old_source.id=OLD.closure_id AND old_source.source_profile_epoch=0
          AND replacement.id=NEW.superseded_by_closure_id AND replacement.source_profile_epoch=1
          AND replacement.source_sequence::numeric>old_source.source_sequence::numeric
          AND replacement.terminal_item_count::numeric>=old_source.terminal_item_count::numeric
      ) THEN
      RAISE EXCEPTION 'PDS outbox supersession requires its durable current-profile replacement';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: pds_guard_retained_checkpoint_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pds_guard_retained_checkpoint_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.group_id IS DISTINCT FROM OLD.group_id
    OR NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id
    OR NEW.package_id IS DISTINCT FROM OLD.package_id
    OR NEW.source_manifest_hash IS DISTINCT FROM OLD.source_manifest_hash
    OR NEW.source_profile IS DISTINCT FROM OLD.source_profile
    OR NEW.source_fingerprint IS DISTINCT FROM OLD.source_fingerprint
    OR NEW.source_closure_hash IS DISTINCT FROM OLD.source_closure_hash
    OR NEW.checkpoint_ordinal IS DISTINCT FROM OLD.checkpoint_ordinal
    OR NEW.checkpoint_previous_closure_hash IS DISTINCT FROM OLD.checkpoint_previous_closure_hash
    OR NEW.checkpoint_item_count IS DISTINCT FROM OLD.checkpoint_item_count
    OR NEW.origin_deployment_id IS DISTINCT FROM OLD.origin_deployment_id
    OR NEW.origin_device_id IS DISTINCT FROM OLD.origin_device_id
    OR NEW.source_sequence IS DISTINCT FROM OLD.source_sequence
    OR NEW.logical_memory_id IS DISTINCT FROM OLD.logical_memory_id
    OR NEW.deletion_floor_token IS DISTINCT FROM OLD.deletion_floor_token
    OR NEW.encrypted_envelope IS DISTINCT FROM OLD.encrypted_envelope THEN
    RAISE EXCEPTION 'PDS retained package identity is immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: pds_reject_closed_source_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pds_reject_closed_source_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  replica_id text;
  append_start text;
  append_end text;
  is_replica_session boolean;
  mutable_columns text[];
  old_metadata jsonb;
  new_metadata jsonb;
  trusted_assignment boolean;
BEGIN
  IF TG_TABLE_NAME = 'pds_session_closures' THEN
    IF NEW.source_profile_epoch IS DISTINCT FROM OLD.source_profile_epoch
      OR NEW.group_id IS DISTINCT FROM OLD.group_id
      OR NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id
      OR NEW.source_session_id IS DISTINCT FROM OLD.source_session_id
      OR NEW.source_sequence IS DISTINCT FROM OLD.source_sequence
      OR NEW.publication_kind IS DISTINCT FROM OLD.publication_kind
      OR NEW.checkpoint_ordinal IS DISTINCT FROM OLD.checkpoint_ordinal
      OR NEW.terminal_cursor IS DISTINCT FROM OLD.terminal_cursor
      OR NEW.terminal_item_count IS DISTINCT FROM OLD.terminal_item_count
      OR NEW.source_closure_hash IS DISTINCT FROM OLD.source_closure_hash
      OR NEW.package_id IS DISTINCT FROM OLD.package_id
      OR NEW.source_manifest_hash IS DISTINCT FROM OLD.source_manifest_hash
      OR NEW.closed_at IS DISTINCT FROM OLD.closed_at THEN
      RAISE EXCEPTION 'PDS Session closure publication is immutable';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'sessions' AND TG_OP IN ('UPDATE', 'DELETE') THEN
    SELECT r.id::text INTO replica_id FROM pds_logical_replicas r WHERE r.local_session_id = OLD.id;
    IF replica_id IS NOT NULL THEN
      IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'PDS replica Sessions are read-only'; END IF;
      mutable_columns := ARRAY['metadata','updated_at','repository_override_identity','repository_assignment_version','repository_assignment_revision_id','folder_assignment',
        'project_override_id','project_override_name','project_override_path','project_override_at','project_override_by_user_id'];
      trusted_assignment := current_setting('koed.pds_replica_append_id',true) IS NOT DISTINCT FROM replica_id;
      trusted_assignment := trusted_assignment OR EXISTS (
        SELECT 1 FROM personal_source_bindings b WHERE b.owner_user_id=OLD.owner_user_id AND b.local_session_id=OLD.id
          AND b.context_version=1 AND b.binding_id::text=current_setting('koed.personal_source_context_binding_id',true)
      );
      old_metadata := OLD.metadata - ARRAY['threadName','threadNameSource','threadNameGeneratedAt','threadNameEditedAt'];
      new_metadata := NEW.metadata - ARRAY['threadName','threadNameSource','threadNameGeneratedAt','threadNameEditedAt'];
      IF current_setting('koed.repository_assignment_cutover',true) = '1'
        AND NEW.repository_assignment_state='historical_unresolved'
        AND NEW.repository_automatic_identity IS NULL AND NEW.repository_override_identity IS NULL
        AND NEW.repository_assignment_version=OLD.repository_assignment_version+1 THEN
        mutable_columns := mutable_columns || ARRAY['repository_assignment_state','repository_automatic_identity'];
      END IF;
      IF trusted_assignment THEN
        mutable_columns := mutable_columns || ARRAY['repository_assignment_state','repository_automatic_identity'];
        old_metadata := old_metadata #- '{pds,repositoryAssignment}';
        new_metadata := new_metadata #- '{pds,repositoryAssignment}';
      END IF;
      IF (to_jsonb(NEW)-mutable_columns) IS DISTINCT FROM (to_jsonb(OLD)-mutable_columns)
        OR new_metadata IS DISTINCT FROM old_metadata THEN
        RAISE EXCEPTION 'PDS replica Sessions are read-only';
      END IF;
    END IF;
    RETURN COALESCE(NEW,OLD);
  END IF;

  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtext('pds-session:' || NEW.session_id::text));
    SELECT EXISTS (
      SELECT 1 FROM pds_logical_replicas r WHERE r.local_session_id = NEW.session_id
    ) INTO is_replica_session;
    IF is_replica_session THEN
      SELECT r.id::text INTO replica_id
      FROM pds_logical_replicas r WHERE r.local_session_id = NEW.session_id;
      append_start := current_setting('koed.pds_replica_append_start', true);
      append_end := current_setting('koed.pds_replica_append_end', true);
      IF current_setting('koed.pds_replica_append_id', true) IS DISTINCT FROM replica_id
        OR NEW.source_transport <> 'pds_relay'
        OR NEW.source_sequence IS NULL
        OR append_start IS NULL OR append_end IS NULL
        OR NEW.source_sequence::numeric < append_start::numeric
        OR NEW.source_sequence::numeric > append_end::numeric THEN
        RAISE EXCEPTION 'PDS replica Sessions accept only trusted checkpoint appends';
      END IF;
    END IF;
    IF EXISTS (
      SELECT 1 FROM pds_session_closures c
      WHERE c.source_session_id = NEW.session_id
        AND c.publication_kind = 'closed' AND c.state = 'ready'
    ) THEN
      RAISE EXCEPTION 'PDS closed source Session cannot accept later items';
    END IF;
  END IF;

  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    SELECT EXISTS (
      SELECT 1 FROM pds_logical_replicas r WHERE r.local_session_id = OLD.session_id
    ) INTO is_replica_session;
    IF is_replica_session OR EXISTS (
      SELECT 1 FROM pds_source_item_mappings m WHERE m.conversation_item_id = OLD.id
    ) THEN
      IF TG_OP = 'DELETE' OR (
        to_jsonb(NEW) - ARRAY[
          'projection_status', 'projection_work_class', 'projection_version',
          'projection_policy_revision', 'projected_at', 'projection_error',
          'memory_excluded_at', 'memory_exclusion_reason', 'memory_excluded_by_user_id',
          'personal_deleted_at', 'personal_deleted_by_user_id', 'personal_deletion_reason'
        ]::text[]
      ) IS DISTINCT FROM (
        to_jsonb(OLD) - ARRAY[
          'projection_status', 'projection_work_class', 'projection_version',
          'projection_policy_revision', 'projected_at', 'projection_error',
          'memory_excluded_at', 'memory_exclusion_reason', 'memory_excluded_by_user_id',
          'personal_deleted_at', 'personal_deleted_by_user_id', 'personal_deletion_reason'
        ]::text[]
      ) THEN
        RAISE EXCEPTION 'PDS source items are read-only';
      END IF;
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: pds_session_recall_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pds_session_recall_ready(candidate_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT
    candidate_session_id IS NULL
    OR NOT EXISTS (
      SELECT 1
      FROM pds_logical_replicas replica
      WHERE replica.local_session_id = candidate_session_id
    )
    OR EXISTS (
      SELECT 1
      FROM pds_logical_replicas replica
      WHERE replica.local_session_id = candidate_session_id
        AND replica.materialization_state = 'ready'
    );
$$;


--
-- Name: pds_set_policy_enabled_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pds_set_policy_enabled_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.enabled AND NOT OLD.enabled THEN NEW.enabled_at = now(); END IF;
  IF NOT NEW.enabled THEN NEW.enabled_at = NULL; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: personal_capture_target_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_capture_target_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO personal_capture_target_changes(owner_user_id,binding_id,operation,"before","after")
  VALUES(NEW.owner_user_id,NEW.binding_id,
    CASE WHEN TG_OP='INSERT' THEN 'preserve'
      WHEN OLD.legacy_detached_at IS NULL AND NEW.legacy_detached_at IS NOT NULL THEN 'detach_legacy'
      ELSE 'repair' END,
    CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,to_jsonb(NEW));
  RETURN NEW;
END;
$$;


--
-- Name: personal_capture_target_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_capture_target_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM sessions s WHERE s.id=NEW.session_id
    AND s.owner_user_id=NEW.owner_user_id AND s.logical_session_id=NEW.logical_session_id
    AND s.visibility='personal') THEN
    RAISE EXCEPTION 'Capture Target source identity does not match its owner';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.version<>1 OR NEW.mode<>'preserved' THEN
      RAISE EXCEPTION 'Capture Target must preserve an exact target before repair';
    END IF;
    IF NEW.origin='legacy_session' THEN
      IF NEW.legacy_detached_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM sessions s WHERE s.id=NEW.session_id
        AND s.project_override_id=NEW.original_target_id
        AND s.project_override_name IS NOT DISTINCT FROM NEW.original_target_name
        AND s.project_override_path IS NOT DISTINCT FROM NEW.original_target_path
        AND s.invalidated_at IS NULL AND s.personal_deleted_at IS NULL) THEN
        RAISE EXCEPTION 'Capture Target must preserve the exact current legacy target';
      END IF;
    ELSIF NEW.origin='legacy_route' THEN
      IF NEW.legacy_detached_at IS NULL OR NOT EXISTS(
        SELECT 1 FROM sessions s JOIN personal_capture_target_routes r ON r.owner_user_id=s.owner_user_id
          AND r.source_scope=repository_scope_id(s.repository_automatic_identity)
        WHERE s.id=NEW.session_id AND s.owner_user_id=NEW.owner_user_id
          AND s.visibility='personal' AND s.invalidated_at IS NULL AND s.personal_deleted_at IS NULL
          AND s.repository_assignment_state='recorded' AND s.repository_override_identity IS NULL AND s.project_override_id IS NULL
          AND r.source_scope=NEW.route_source_scope AND r.target_id=NEW.original_target_id
          AND r.target_name IS NOT DISTINCT FROM NEW.original_target_name AND r.target_path IS NOT DISTINCT FROM NEW.original_target_path
      ) THEN
        RAISE EXCEPTION 'Capture Target route must match the exact recorded source';
      END IF;
    ELSE RAISE EXCEPTION 'Unsupported Capture Target origin';
    END IF;
  ELSE
    IF ROW(NEW.binding_id,NEW.owner_user_id,NEW.session_id,NEW.logical_session_id,NEW.origin,NEW.route_source_scope,
      NEW.original_target_id,NEW.original_target_name,NEW.original_target_path,NEW.created_at)
      IS DISTINCT FROM ROW(OLD.binding_id,OLD.owner_user_id,OLD.session_id,OLD.logical_session_id,OLD.origin,OLD.route_source_scope,
      OLD.original_target_id,OLD.original_target_name,OLD.original_target_path,OLD.created_at)
      OR NEW.version<>OLD.version+1
      OR (OLD.legacy_detached_at IS NOT NULL AND NEW.legacy_detached_at IS DISTINCT FROM OLD.legacy_detached_at) THEN
      RAISE EXCEPTION 'Capture Target identity is immutable and updates require the next version';
    END IF;
    IF OLD.legacy_detached_at IS NULL AND NEW.legacy_detached_at IS NOT NULL
      AND EXISTS(SELECT 1 FROM sessions s WHERE s.id=NEW.session_id AND s.project_override_id IS NOT NULL) THEN
      RAISE EXCEPTION 'Capture Target detachment requires the legacy role to be cleared atomically';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: personal_capture_target_review_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_capture_target_review_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(NEW.review_id,NEW.owner_user_id,NEW.binding_id,NEW.expected_state,NEW.choice,NEW.preview,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.review_id,OLD.owner_user_id,OLD.binding_id,OLD.expected_state,OLD.choice,OLD.preview,OLD.created_at)
    OR OLD.applied_at IS NOT NULL OR NEW.applied_at IS NULL THEN
    RAISE EXCEPTION 'Capture Target review is immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: personal_legacy_capture_detachment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_legacy_capture_detachment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM sessions s WHERE s.id=NEW.id AND s.owner_user_id=NEW.owner_user_id
    AND s.visibility='personal' AND s.invalidated_at IS NULL AND s.personal_deleted_at IS NULL
    AND s.project_override_id IS NULL AND NOT EXISTS(
      SELECT 1 FROM personal_capture_target_bindings b WHERE b.owner_user_id=s.owner_user_id AND b.session_id=s.id
      AND b.logical_session_id=s.logical_session_id AND b.legacy_detached_at IS NOT NULL
    )) THEN RAISE EXCEPTION 'Legacy source detachment must preserve its Capture Target in the same transaction'; END IF;
  RETURN NULL;
END;
$$;


--
-- Name: personal_legacy_source_archive_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_legacy_source_archive_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM sessions s WHERE s.id=NEW.session_id AND s.owner_user_id=NEW.owner_user_id
    AND NEW.evidence=personal_legacy_source_evidence(s)) THEN
    RAISE EXCEPTION 'Legacy source evidence must match the actual owned Session';
  END IF;
  RETURN NEW;
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_user_id uuid,
    visibility public.visibility_scope DEFAULT 'personal'::public.visibility_scope NOT NULL,
    external_session_id text,
    source_runtime public.source_runtime NOT NULL,
    capture_method public.capture_method NOT NULL,
    idempotency_key text,
    source_hash text,
    model text,
    cwd text,
    source_kind text,
    source_adapter_version text,
    external_thread_id text,
    forked_from_external_thread_id text,
    parent_session_id uuid,
    parent_external_thread_id text,
    agent_nickname text,
    agent_role text,
    agent_path text,
    thread_source text,
    source_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    invalidated_at timestamp with time zone,
    invalidation_reason text,
    personal_deleted_at timestamp with time zone,
    personal_deleted_by_user_id uuid,
    personal_deletion_reason text,
    captured_project_provenance jsonb DEFAULT '{}'::jsonb NOT NULL,
    automatic_project_id text,
    automatic_project_name text,
    automatic_project_path text,
    automatic_project_detected_at timestamp with time zone,
    project_override_id text,
    project_override_name text,
    project_override_path text,
    project_override_at timestamp with time zone,
    project_override_by_user_id uuid,
    source_fingerprint text,
    captured_project jsonb DEFAULT '{}'::jsonb NOT NULL,
    import_observed_at timestamp with time zone,
    logical_session_id uuid DEFAULT gen_random_uuid() NOT NULL,
    repository_assignment_state text DEFAULT 'historical_unresolved'::text NOT NULL,
    repository_assignment_version integer DEFAULT 1 NOT NULL,
    repository_automatic_identity jsonb,
    repository_override_identity jsonb,
    folder_assignment jsonb DEFAULT '{"original": {"state": "unresolved", "reason": "historical_unresolved"}, "revision": 1, "correction": {"state": "original"}}'::jsonb NOT NULL,
    repository_assignment_revision_id uuid,
    CONSTRAINT sessions_automatic_project_shape_check CHECK ((((automatic_project_id IS NULL) AND (automatic_project_name IS NULL) AND (automatic_project_path IS NULL) AND (automatic_project_detected_at IS NULL)) OR ((automatic_project_id IS NOT NULL) AND (automatic_project_name IS NOT NULL) AND (automatic_project_detected_at IS NOT NULL)))),
    CONSTRAINT sessions_personal_owner_check CHECK (((visibility = 'personal'::public.visibility_scope) AND (owner_user_id IS NOT NULL))),
    CONSTRAINT sessions_project_override_shape_check CHECK ((((project_override_id IS NULL) AND (project_override_name IS NULL) AND (project_override_path IS NULL) AND (project_override_at IS NULL) AND (project_override_by_user_id IS NULL)) OR ((project_override_id IS NOT NULL) AND (project_override_name IS NOT NULL) AND (project_override_at IS NOT NULL) AND (project_override_by_user_id IS NOT NULL)))),
    CONSTRAINT sessions_repository_assignment_shape_check CHECK (((repository_assignment_state = ANY (ARRAY['recorded'::text, 'historical_unresolved'::text])) AND (repository_assignment_version > 0) AND ((repository_assignment_state <> 'historical_unresolved'::text) OR (repository_automatic_identity IS NULL))))
);


--
-- Name: personal_legacy_source_evidence(public.sessions); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_legacy_source_evidence(s public.sessions) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_build_object('sessionId',s.id,'ownerUserId',s.owner_user_id,'logicalSessionId',s.logical_session_id,
    'assignmentVersion',s.repository_assignment_version,'assignmentRevisionId',s.repository_assignment_revision_id,
    'automaticIdentity',s.repository_automatic_identity,'overrideIdentity',s.repository_override_identity,
    'overrideId',s.project_override_id,'overrideName',s.project_override_name,'overridePath',s.project_override_path,
    'overrideAt',s.project_override_at,'overrideByUserId',s.project_override_by_user_id,
    'invalidatedAt',s.invalidated_at,'deletedAt',s.personal_deleted_at);
$$;


--
-- Name: personal_legacy_source_write_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_legacy_source_write_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='UPDATE' AND ROW(NEW.project_override_id,NEW.project_override_name,NEW.project_override_path,NEW.project_override_at,NEW.project_override_by_user_id)
    IS NOT DISTINCT FROM ROW(OLD.project_override_id,OLD.project_override_name,OLD.project_override_path,OLD.project_override_at,OLD.project_override_by_user_id) THEN RETURN NEW; END IF;
  IF NEW.project_override_id IS NULL AND NEW.project_override_name IS NULL AND NEW.project_override_path IS NULL
    AND NEW.project_override_at IS NULL AND NEW.project_override_by_user_id IS NULL THEN
    IF TG_OP='INSERT' THEN RETURN NEW; END IF;
    IF EXISTS(SELECT 1 FROM personal_legacy_source_assignments a WHERE a.owner_user_id=OLD.owner_user_id
      AND a.session_id=OLD.id AND a.evidence=personal_legacy_source_evidence(OLD)) AND (
      OLD.invalidated_at IS NOT NULL OR OLD.personal_deleted_at IS NOT NULL OR EXISTS(
        SELECT 1 FROM personal_capture_target_bindings b WHERE b.owner_user_id=OLD.owner_user_id AND b.session_id=OLD.id
        AND b.logical_session_id=OLD.logical_session_id AND b.legacy_detached_at IS NULL
        AND (b.mode<>'preserved' OR b.original_target_id=OLD.project_override_id)
      )) THEN RETURN NEW;
    END IF;
  END IF;
  RAISE EXCEPTION 'Legacy Project source writes are retired; use inclusion or source-context controls';
END;
$$;


--
-- Name: personal_membership_change_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_membership_change_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Personal membership revisions are immutable';
END;
$$;


--
-- Name: personal_selection_observe(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_selection_observe() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  row_value jsonb;
  candidates jsonb[];
  owner_id uuid;
  session_id uuid;
BEGIN
  IF TG_OP='UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
  candidates := CASE WHEN TG_OP='INSERT' THEN ARRAY[to_jsonb(NEW)]
    WHEN TG_OP='DELETE' THEN ARRAY[to_jsonb(OLD)] ELSE ARRAY[to_jsonb(OLD),to_jsonb(NEW)] END;
  FOREACH row_value IN ARRAY candidates LOOP
    owner_id := NULL;
    session_id := NULL;
    IF TG_ARGV[1]='owner' THEN
      owner_id := (row_value->>'owner_user_id')::uuid;
      IF TG_ARGV[2]='self' THEN session_id := (row_value->>'id')::uuid;
      ELSIF TG_ARGV[2]<>'' THEN session_id := (row_value->>TG_ARGV[2])::uuid;
      END IF;
    ELSIF TG_ARGV[1]='binding' THEN
      SELECT b.owner_user_id,b.local_session_id INTO owner_id,session_id
      FROM personal_source_bindings b WHERE b.binding_id=(row_value->>'binding_id')::uuid;
    ELSIF TG_ARGV[1]='pds_replica' THEN
      SELECT r.owner_user_id,r.local_session_id INTO owner_id,session_id
      FROM pds_logical_replicas r WHERE r.id=(row_value->>'replica_id')::uuid;
    ELSIF TG_ARGV[1]='logical_memory' THEN
      INSERT INTO personal_selection_changes(owner_user_id,kind,local_session_id)
      SELECT DISTINCT l.owner_user_id,TG_ARGV[0],l.local_session_id
      FROM local_captured_session_logical_memories l JOIN users u ON u.id=l.owner_user_id
      WHERE l.logical_memory_id=(row_value->>'logical_memory_id')::uuid;
      CONTINUE;
    END IF;
    -- Owner deletion cascades need no orphan event. Source deletion events
    -- retain their identifier without a Session FK or private source body.
    IF owner_id IS NOT NULL AND EXISTS(SELECT 1 FROM users WHERE id=owner_id) THEN
      INSERT INTO personal_selection_changes(owner_user_id,kind,local_session_id)
      VALUES(owner_id,TG_ARGV[0],session_id);
    END IF;
  END LOOP;
  RETURN NULL;
END;
$$;


--
-- Name: prevent_retention_policy_shortening_child_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_retention_policy_shortening_child_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'retention policy shortening snapshot and migration rows are immutable';
END;
$$;


--
-- Name: queue_source_repository_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_source_repository_assignment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.repository_assignment_version IS NOT DISTINCT FROM OLD.repository_assignment_version THEN
    RETURN NEW;
  END IF;
  INSERT INTO sync_outbox_entries(sync_relationship_id,idempotency_key,request_hash,payload_manifest)
  SELECT relationship.id,
    'repository-assignment:' || NEW.id::text || ':' || NEW.repository_assignment_version::text,
    encode(digest(relationship.id::text || ':' || NEW.id::text || ':' || NEW.repository_assignment_version::text,'sha256'),'hex'),
    jsonb_build_object('kind','repository_assignment','sessionId',NEW.id,'assignmentVersion',NEW.repository_assignment_version)
  FROM cross_identity_sync_relationships relationship
  JOIN memory_replicas replica ON replica.id=relationship.local_replica_id
  JOIN local_captured_session_logical_memories local_memory
    ON local_memory.logical_memory_id=relationship.logical_memory_id
    AND local_memory.owner_user_id=relationship.local_user_id
  WHERE relationship.side='source' AND relationship.revoked_at IS NULL
    AND relationship.state NOT IN ('revoked','purge_pending')
    AND replica.replica_role='source' AND replica.encryption_scope='personal'
    AND local_memory.local_session_id=NEW.id AND relationship.local_user_id=NEW.owner_user_id
  ON CONFLICT(sync_relationship_id,idempotency_key) DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: record_sync_semantic_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_sync_semantic_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  source_row memory_events%ROWTYPE;
  change_cursor bigint;
  change_operation sync_change_operation;
  change_hash text;
BEGIN
  source_row := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  IF source_row.session_id IS NULL OR source_row.event_type <> 'captured' THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  change_operation := CASE
    WHEN TG_OP = 'DELETE'
      OR source_row.invalidated_at IS NOT NULL
      OR source_row.personal_deleted_at IS NOT NULL
      THEN 'delete'::sync_change_operation
    ELSE 'upsert'::sync_change_operation
  END;
  change_hash := encode(
    digest(
      concat_ws(
        '|',
        source_row.id::text,
        change_operation::text,
        coalesce(source_row.source_event_time::text, ''),
        coalesce(source_row.source_sequence::text, ''),
        coalesce(source_row.seal_reason, ''),
        coalesce(source_row.updated_at::text, source_row.created_at::text)
      ),
      'sha256'
    ),
    'hex'
  );

  INSERT INTO sync_semantic_changes (
    session_id, memory_event_id, origin_event_id, operation, revision_hash
  ) VALUES (
    source_row.session_id,
    CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE source_row.id END,
    source_row.id,
    change_operation,
    change_hash
  ) RETURNING cursor INTO change_cursor;

  INSERT INTO sync_outbox_entries (
    sync_relationship_id, idempotency_key, request_hash, payload_manifest
  )
  SELECT
    relationship.id,
    'changes',
    encode(
      digest(relationship.id::text || ':' || change_cursor::text, 'sha256'),
      'hex'
    ),
    jsonb_build_object('latestChangeCursor', change_cursor)
  FROM cross_identity_sync_relationships relationship
  JOIN memory_replicas replica ON replica.id = relationship.local_replica_id
  JOIN local_captured_session_logical_memories local_memory
    ON local_memory.logical_memory_id = replica.logical_memory_id
  WHERE relationship.side = 'source'
    AND relationship.revoked_at IS NULL
    AND relationship.state NOT IN ('paused', 'revoked', 'purge_pending')
    AND local_memory.local_session_id = source_row.session_id
  ON CONFLICT (sync_relationship_id, idempotency_key) DO UPDATE SET
    state = CASE
      WHEN sync_outbox_entries.state = 'processing'
        AND sync_outbox_entries.lease_expires_at > now()
        THEN sync_outbox_entries.state
      ELSE 'pending'::sync_queue_entry_state
    END,
    attempt_count = CASE
      WHEN sync_outbox_entries.state = 'processing'
        AND sync_outbox_entries.lease_expires_at > now()
        THEN sync_outbox_entries.attempt_count
      ELSE 0
    END,
    request_hash = EXCLUDED.request_hash,
    payload_manifest = EXCLUDED.payload_manifest,
    available_at = now(),
    processed_at = NULL,
    claim_token = CASE
      WHEN sync_outbox_entries.state = 'processing'
        AND sync_outbox_entries.lease_expires_at > now()
        THEN sync_outbox_entries.claim_token
      ELSE NULL
    END,
    lease_expires_at = CASE
      WHEN sync_outbox_entries.state = 'processing'
        AND sync_outbox_entries.lease_expires_at > now()
        THEN sync_outbox_entries.lease_expires_at
      ELSE NULL
    END,
    last_error_message = NULL,
    updated_at = now();

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: repository_scope_id(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repository_scope_id(identity jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE WHEN identity ->> 'kind' IN ('portable_repository', 'device_local_repository', 'non_git_project', 'local_project')
    AND identity ->> 'key' IS NOT NULL THEN
      'repository:{"kind":' || to_json(identity ->> 'kind')::text || ',"key":' || to_json(identity ->> 'key')::text || ',"device":' || CASE WHEN identity ->> 'kind' = 'portable_repository' THEN 'null' ELSE to_json(identity ->> 'originatingDeviceId')::text END || '}'
    ELSE null END;
$$;


--
-- Name: repository_scope_matches(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repository_scope_matches(identity jsonb, scope text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$
DECLARE target jsonb;
BEGIN
  IF identity IS NULL OR scope IS NULL OR left(scope, 11) <> 'repository:' THEN
    RETURN false;
  END IF;
  BEGIN
    target := substring(scope FROM 12)::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN false;
  END;
  RETURN coalesce(
    identity ->> 'kind' IN ('portable_repository', 'device_local_repository', 'non_git_project', 'local_project')
    AND identity ->> 'kind' = target ->> 'kind'
    AND identity ->> 'key' IS NOT NULL
    AND identity ->> 'key' = target ->> 'key'
    AND (identity ->> 'kind' = 'portable_repository'
      OR identity ->> 'originatingDeviceId' = target ->> 'device'), false);
END;
$$;


--
-- Name: schedule_personal_project_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_personal_project_defaults() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.owner_user_id IS NOT NULL THEN
    INSERT INTO personal_project_default_reconciliation(owner_user_id) VALUES(NEW.owner_user_id)
    ON CONFLICT(owner_user_id) DO UPDATE SET generation=personal_project_default_reconciliation.generation+1,pending=true,retry_at=now(),updated_at=now();
    PERFORM pg_notify('koed_project_defaults','source_changed');
  END IF;
  RETURN NEW;
END $$;


