    CONSTRAINT csm_rule_delivery_destination_check CHECK ((((operation_kind = 'control'::text) AND (share_grant_id IS NOT NULL) AND (logical_grant_id IS NULL)) OR ((operation_kind = 'conversation_create'::text) AND (share_grant_id IS NULL) AND (logical_grant_id IS NOT NULL)) OR ((operation_kind = ANY (ARRAY['repository_create'::text, 'repository_control'::text, 'detail'::text, 'content_policy'::text, 'publisher_takeover'::text])) AND (share_grant_id IS NULL) AND (logical_grant_id IS NULL)) OR ((operation_kind = ANY (ARRAY['workspace_exclude'::text, 'workspace_restore'::text])) AND (logical_grant_id IS NULL)))),
    CONSTRAINT csm_rule_delivery_failure_check CHECK (((failure_code IS NULL) OR (failure_code = ANY (ARRAY['offline'::text, 'remote_unavailable'::text, 'source_unavailable'::text, 'authority_unavailable'::text, 'conflict'::text, 'response_invalid'::text])))),
    CONSTRAINT csm_rule_delivery_payload_check CHECK (((length(intent_hash) = 64) AND (((protected_dto IS NOT NULL) AND (protected_dto_hash IS NOT NULL) AND (length(protected_dto_hash) = 64)) OR ((state = 'needs_review'::text) AND (protected_dto IS NULL) AND (protected_dto_hash IS NULL))))),
    CONSTRAINT csm_rule_delivery_state_check CHECK (((state = ANY (ARRAY['queued'::text, 'acknowledged'::text, 'needs_review'::text])) AND (attempt_count >= 0) AND (lease_version >= 0)))
);


