    CONSTRAINT collaboration_threads_sequence_check CHECK ((next_sequence > 0)),
    CONSTRAINT collaboration_threads_shape_check CHECK ((((scope = 'personal'::public.collaboration_scope) AND (kind = 'personal_channel'::public.collaboration_thread_kind) AND (personal_owner_user_id IS NOT NULL) AND (team_id IS NULL) AND (team_workspace_id IS NULL) AND (system_key IS NULL) AND (name_marker = '[koed encrypted collaboration name]'::text) AND (length(normalized_name_hash) = 64) AND (participant_key IS NULL) AND (shared_logical_memory_id IS NULL) AND (share_grant_id IS NULL)) OR ((scope = 'team'::public.collaboration_scope) AND (kind = 'workspace_channel'::public.collaboration_thread_kind) AND (personal_owner_user_id IS NULL) AND (team_id IS NOT NULL) AND (team_workspace_id IS NOT NULL) AND (((system_key IS NULL) AND (name_marker = '[koed encrypted collaboration name]'::text) AND (length(normalized_name_hash) = 64)) OR ((system_key = 'workspace.general'::text) AND (((name_marker IS NULL) AND (normalized_name_hash IS NULL)) OR ((name_marker = '[koed encrypted collaboration name]'::text) AND (length(normalized_name_hash) = 64))))) AND (participant_key IS NULL) AND (shared_logical_memory_id IS NULL) AND (share_grant_id IS NULL)) OR ((scope = 'team'::public.collaboration_scope) AND (kind = ANY (ARRAY['dm'::public.collaboration_thread_kind, 'group_dm'::public.collaboration_thread_kind])) AND (personal_owner_user_id IS NULL) AND (team_id IS NOT NULL) AND (team_workspace_id IS NULL) AND (system_key IS NULL) AND (name_marker IS NULL) AND (topic_marker IS NULL) AND (normalized_name_hash IS NULL) AND (length(participant_key) = 64) AND (shared_logical_memory_id IS NULL) AND (share_grant_id IS NULL)) OR ((scope = 'team'::public.collaboration_scope) AND (kind = 'shared_session_discussion'::public.collaboration_thread_kind) AND (personal_owner_user_id IS NULL) AND (team_id IS NOT NULL) AND (team_workspace_id IS NOT NULL) AND (system_key IS NULL) AND (name_marker IS NULL) AND (topic_marker IS NULL) AND (normalized_name_hash IS NULL) AND (participant_key IS NULL) AND (shared_logical_memory_id IS NOT NULL) AND (share_grant_id IS NOT NULL)))),
    CONSTRAINT collaboration_threads_system_key_check CHECK (((system_key IS NULL) OR (system_key = 'workspace.general'::text))),
    CONSTRAINT collaboration_threads_topic_marker_check CHECK (((topic_marker IS NULL) OR (topic_marker = '[koed encrypted collaboration topic]'::text))),
    CONSTRAINT collaboration_threads_version_check CHECK ((version > 0))
);


