    released_at timestamp with time zone,
    CONSTRAINT legal_holds_reason_check CHECK (((length(TRIM(BOTH FROM authority)) > 0) AND (length(TRIM(BOTH FROM reason_code)) > 0) AND (length(reason_hash) = 64))),
    CONSTRAINT legal_holds_release_lifecycle_check CHECK ((((state = 'active'::public.legal_hold_state) AND (release_requested_at IS NULL) AND (release_confirmed_at IS NULL) AND (released_at IS NULL)) OR ((state = 'release_pending'::public.legal_hold_state) AND (release_requested_at IS NOT NULL) AND (release_confirmed_at IS NULL) AND (released_at IS NULL)) OR ((state = 'released'::public.legal_hold_state) AND (release_requested_at IS NOT NULL) AND (release_confirmed_at IS NOT NULL) AND (released_at IS NOT NULL) AND (single_holder_release_exception OR (release_confirmed_by_user_id IS DISTINCT FROM release_requested_by_user_id))))),
    CONSTRAINT legal_holds_target_check CHECK ((((scope = 'team'::public.legal_hold_scope) AND (team_id IS NOT NULL) AND (team_workspace_id IS NULL) AND (thread_id IS NULL) AND (share_grant_id IS NULL) AND (representation_id IS NULL) AND (owner_private_replica_id IS NULL) AND (logical_memory_id IS NULL)) OR ((scope = 'workspace'::public.legal_hold_scope) AND (team_id IS NOT NULL) AND (team_workspace_id IS NOT NULL) AND (thread_id IS NULL) AND (share_grant_id IS NULL) AND (representation_id IS NULL) AND (owner_private_replica_id IS NULL) AND (logical_memory_id IS NULL)) OR ((scope = 'thread'::public.legal_hold_scope) AND (team_id IS NOT NULL) AND (thread_id IS NOT NULL) AND (share_grant_id IS NULL) AND (representation_id IS NULL) AND (owner_private_replica_id IS NULL) AND (logical_memory_id IS NULL)) OR ((scope = 'grant_representation'::public.legal_hold_scope) AND (team_id IS NOT NULL) AND (team_workspace_id IS NOT NULL) AND (share_grant_id IS NOT NULL) AND (representation_id IS NOT NULL) AND (representation IS NOT NULL) AND (source_revision >= 0) AND (owner_private_replica_id IS NULL) AND (logical_memory_id IS NOT NULL)) OR ((scope = 'team_message_range'::public.legal_hold_scope) AND (team_id IS NOT NULL) AND (thread_id IS NOT NULL) AND (share_grant_id IS NULL) AND (representation_id IS NULL) AND (owner_private_replica_id IS NULL) AND (logical_memory_id IS NULL) AND (((message_range_start > 0) AND (message_range_end >= message_range_start)) OR ((message_time_start IS NOT NULL) AND (message_time_end >= message_time_start)))) OR ((scope = 'owner_private_replica'::public.legal_hold_scope) AND (team_id IS NULL) AND (team_workspace_id IS NULL) AND (thread_id IS NULL) AND (share_grant_id IS NULL) AND (representation_id IS NULL) AND (owner_private_replica_id IS NOT NULL) AND (logical_memory_id IS NOT NULL))))
);


