);


--
-- Name: logical_memory_source_revision_bindings; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.logical_memory_source_revision_bindings AS
 SELECT revision.id AS source_revision_id,
    revision.logical_memory_id,
    revision.owner_principal_id,
    revision.source_kind,
    revision.revision AS generic_revision,
    captured.source_cursor AS source_revision,
    captured.source_session_id,
    NULL::uuid AS source_note_id,
    NULL::uuid AS source_memory_event_id
   FROM (public.logical_memory_source_revisions revision
     JOIN public.captured_session_source_revisions captured ON ((captured.source_revision_id = revision.id)))
UNION ALL
 SELECT revision.id AS source_revision_id,
    revision.logical_memory_id,
    revision.owner_principal_id,
    revision.source_kind,
    revision.revision AS generic_revision,
    (note.revision)::bigint AS source_revision,
    NULL::uuid AS source_session_id,
    note.source_note_id,
    note.source_memory_event_id
   FROM (public.logical_memory_source_revisions revision
     JOIN public.personal_note_source_revisions note ON ((note.source_revision_id = revision.id)));


