    CONSTRAINT managed_conversation_authority_quarantine_check CHECK ((((quarantined_at IS NULL) AND (quarantine_reason IS NULL)) OR ((quarantined_at IS NOT NULL) AND ((length(TRIM(BOTH FROM quarantine_reason)) >= 1) AND (length(TRIM(BOTH FROM quarantine_reason)) <= 120)))))
);


--
-- Name: managed_conversation_commands; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.managed_conversation_commands (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_user_id uuid NOT NULL,
    execution_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    sequence integer NOT NULL,
    command_kind text NOT NULL,
    target_deployment_id uuid,
    target_device_id uuid,
    request_digest text NOT NULL,
    client_user_message_id uuid,
    execution_generation integer NOT NULL,
    encrypted_payload jsonb,
    state text DEFAULT 'queued'::text NOT NULL,
    blocked_on_kind text,
    blocked_on_id uuid,
    attempts integer DEFAULT 0 NOT NULL,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    result jsonb,
    last_error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    dispatching_at timestamp with time zone,
    completed_at timestamp with time zone,
    CONSTRAINT managed_conversation_commands_checkpoint_pending_check CHECK ((((result ->> 'phase'::text) IS DISTINCT FROM 'checkpoint_pending'::text) OR ((command_kind = 'prompt'::text) AND (state = ANY (ARRAY['queued'::text, 'dispatching'::text])) AND ((result ->> 'sourceGenerationId'::text) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (((result -> 'providerTurnId'::text) = 'null'::jsonb) OR ((jsonb_typeof((result -> 'providerTurnId'::text)) = 'string'::text) AND ((length(TRIM(BOTH FROM (result ->> 'providerTurnId'::text))) >= 1) AND (length(TRIM(BOTH FROM (result ->> 'providerTurnId'::text))) <= 512))))))),
    CONSTRAINT managed_conversation_commands_kind_check CHECK ((command_kind = ANY (ARRAY['start'::text, 'prompt'::text, 'interrupt'::text, 'quiesce'::text, 'stop'::text, 'verify_target'::text, 'restore'::text, 'checkpoint_restore'::text, 'fork_prepare'::text, 'fork_create'::text, 'file_browse'::text, 'file_read'::text, 'file_search'::text, 'file_mention'::text]))),
    CONSTRAINT managed_conversation_commands_lease_check CHECK ((((lease_token IS NULL) AND (lease_expires_at IS NULL)) OR ((lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL)))),
    CONSTRAINT managed_conversation_commands_shape_check CHECK (((sequence >= 0) AND (execution_generation > 0) AND (attempts >= 0) AND (request_digest ~ '^[0-9a-f]{64}$'::text) AND (((state = 'blocked'::text) AND (blocked_on_kind = ANY (ARRAY['source_replica'::text, 'source_registration'::text, 'runtime_binding'::text])) AND (blocked_on_id IS NOT NULL) AND ((blocked_on_kind <> 'runtime_binding'::text) OR ((command_kind = 'start'::text) AND (blocked_on_id = execution_id)))) OR ((state <> 'blocked'::text) AND (blocked_on_kind IS NULL) AND (blocked_on_id IS NULL))) AND ((command_kind <> ALL (ARRAY['prompt'::text, 'checkpoint_restore'::text, 'file_browse'::text, 'file_read'::text, 'file_search'::text, 'file_mention'::text])) OR (encrypted_payload IS NOT NULL)) AND (((command_kind = 'prompt'::text) AND (client_user_message_id IS NOT NULL)) OR ((command_kind <> 'prompt'::text) AND (client_user_message_id IS NULL))) AND (((command_kind = ANY (ARRAY['verify_target'::text, 'restore'::text, 'fork_create'::text])) AND (target_deployment_id IS NOT NULL) AND (target_device_id IS NOT NULL)) OR ((command_kind <> ALL (ARRAY['verify_target'::text, 'restore'::text, 'fork_create'::text])) AND (target_deployment_id IS NULL) AND (target_device_id IS NULL))))),
    CONSTRAINT managed_conversation_commands_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'blocked'::text, 'dispatching'::text, 'completed'::text, 'indeterminate'::text, 'failed'::text, 'canceled'::text])))
);


