CREATE TABLE public.managed_conversation_terminals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_user_id uuid NOT NULL,
    execution_id uuid NOT NULL,
    execution_generation integer NOT NULL,
    checkout_id uuid NOT NULL,
    runner_deployment_id uuid NOT NULL,
    runner_device_id uuid NOT NULL,
    lifecycle_generation integer DEFAULT 1 NOT NULL,
    shell_profile_id text NOT NULL,
    state text DEFAULT 'creating'::text NOT NULL,
    columns integer NOT NULL,
    rows integer NOT NULL,
    idempotency_key text NOT NULL,
    request_digest text NOT NULL,
    exit_code integer,
    exit_signal integer,
    failure_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    detached_at timestamp with time zone,
    stopped_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT managed_conversation_terminals_lifecycle_check CHECK ((((state = 'creating'::text) AND (started_at IS NULL) AND (stopped_at IS NULL) AND (exit_code IS NULL) AND (exit_signal IS NULL) AND (failure_code IS NULL)) OR ((state = ANY (ARRAY['running'::text, 'detached'::text, 'stopping'::text])) AND (started_at IS NOT NULL) AND (stopped_at IS NULL) AND (exit_code IS NULL) AND (exit_signal IS NULL) AND (failure_code IS NULL)) OR ((state = 'unknown'::text) AND (started_at IS NOT NULL) AND (stopped_at IS NULL) AND (exit_code IS NULL) AND (exit_signal IS NULL) AND (failure_code IS NOT NULL)) OR ((state = 'exited'::text) AND (started_at IS NOT NULL) AND (stopped_at IS NOT NULL) AND (exit_code IS NOT NULL) AND (failure_code IS NULL)) OR ((state = 'failed'::text) AND (stopped_at IS NOT NULL) AND (exit_code IS NULL) AND (exit_signal IS NULL) AND (failure_code IS NOT NULL)))),
    CONSTRAINT managed_conversation_terminals_shape_check CHECK (((execution_generation > 0) AND (lifecycle_generation > 0) AND (shell_profile_id = 'system_default'::text) AND (state = ANY (ARRAY['creating'::text, 'running'::text, 'detached'::text, 'stopping'::text, 'unknown'::text, 'exited'::text, 'failed'::text])) AND ((columns >= 20) AND (columns <= 500)) AND ((rows >= 5) AND (rows <= 300)) AND ((length(TRIM(BOTH FROM idempotency_key)) >= 16) AND (length(TRIM(BOTH FROM idempotency_key)) <= 160)) AND (request_digest ~ '^[0-9a-f]{64}$'::text) AND ((failure_code IS NULL) OR (failure_code ~ '^[A-Za-z][A-Za-z0-9_.-]{0,119}$'::text))))
);


--
-- Name: memory_answer_tasks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.memory_answer_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_user_id uuid NOT NULL,
    visibility public.visibility_scope DEFAULT 'personal'::public.visibility_scope NOT NULL,
    origin text NOT NULL,
    invocation_key text,
    request_snapshot jsonb NOT NULL,
    result_snapshot jsonb,
    question_id uuid,
    status text DEFAULT 'accepted'::text NOT NULL,
    status_message text,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_owner text,
    lease_until timestamp with time zone,
    fence_generation integer DEFAULT 0 NOT NULL,
    cancel_requested_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    started_at timestamp with time zone,
    last_progress_at timestamp with time zone,
    completed_at timestamp with time zone,
    failed_at timestamp with time zone,
    last_error_code text,
    last_error_message text,
    version integer DEFAULT 1 NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    team_workspace_id uuid,
    team_authorization jsonb,
    CONSTRAINT memory_answer_tasks_attempts_check CHECK (((attempt_count >= 0) AND (max_attempts >= 1) AND (attempt_count <= max_attempts))),
    CONSTRAINT memory_answer_tasks_fence_version_check CHECK (((fence_generation >= 0) AND (version >= 1))),
    CONSTRAINT memory_answer_tasks_lease_check CHECK ((((status = ANY (ARRAY['running'::text, 'cancel_requested'::text])) AND (lease_owner IS NOT NULL) AND (lease_until IS NOT NULL)) OR ((status <> ALL (ARRAY['running'::text, 'cancel_requested'::text])) AND (lease_owner IS NULL) AND (lease_until IS NULL)))),
    CONSTRAINT memory_answer_tasks_origin_check CHECK ((origin = ANY (ARRAY['mcp'::text, 'pi_extension'::text]))),
    CONSTRAINT memory_answer_tasks_personal_owner_check CHECK (((visibility = 'personal'::public.visibility_scope) AND (owner_user_id IS NOT NULL))),
    CONSTRAINT memory_answer_tasks_status_check CHECK ((status = ANY (ARRAY['accepted'::text, 'running'::text, 'cancel_requested'::text, 'completed'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT memory_answer_tasks_team_authority_check CHECK ((((team_workspace_id IS NULL) AND (team_authorization IS NULL)) OR ((team_workspace_id IS NOT NULL) AND (team_authorization IS NOT NULL)))),
    CONSTRAINT memory_answer_tasks_terminal_check CHECK ((((status = 'completed'::text) AND (result_snapshot IS NOT NULL) AND (question_id IS NOT NULL) AND (completed_at IS NOT NULL) AND (failed_at IS NULL) AND (cancelled_at IS NULL)) OR ((status = 'failed'::text) AND (result_snapshot IS NULL) AND (question_id IS NULL) AND (completed_at IS NULL) AND (failed_at IS NOT NULL) AND (cancelled_at IS NULL)) OR ((status = 'cancelled'::text) AND (result_snapshot IS NULL) AND (question_id IS NULL) AND (completed_at IS NULL) AND (failed_at IS NULL) AND (cancelled_at IS NOT NULL)) OR ((status <> ALL (ARRAY['completed'::text, 'failed'::text, 'cancelled'::text])) AND (result_snapshot IS NULL) AND (question_id IS NULL) AND (completed_at IS NULL) AND (failed_at IS NULL) AND (cancelled_at IS NULL))))
);


