    visibility public.visibility_scope NOT NULL,
    embedding_model text NOT NULL,
    embedding_dimensions integer NOT NULL,
    embedding_version text NOT NULL,
    source_hash text NOT NULL,
    source_chunk_index integer DEFAULT 0 NOT NULL,
    source_chunk_count integer DEFAULT 1 NOT NULL,
    source_text text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    invalidated_at timestamp with time zone,
    invalidation_reason text,
    personal_deleted_at timestamp with time zone,
    personal_deleted_by_user_id uuid,
    personal_deletion_reason text,
    queryable_vector_strategy text DEFAULT 'trusted_backend_pgvector_v1'::text NOT NULL,
    search_boundary text DEFAULT 'owner_user_dynamic_grants'::text NOT NULL,
    canonical_embedding_state text DEFAULT 'not_stored'::text NOT NULL,
    model_artifact_hash text,
    tokenizer text,
    input_transform text,
    pooling text,
    normalization text,
    input_token_count integer,
    curated_memory_assertion_id uuid,
    embedding_source_content_hash text NOT NULL,
    embedding_input_hash text NOT NULL,
    CONSTRAINT memory_embeddings_canonical_embedding_state_check CHECK ((canonical_embedding_state = ANY (ARRAY['not_stored'::text, 'encrypted_payload'::text]))),
    CONSTRAINT memory_embeddings_embedding_dimensions_check CHECK ((embedding_dimensions = ANY (ARRAY[384, 1024, 1536, 3072]))),
    CONSTRAINT memory_embeddings_input_token_count_check CHECK (((input_token_count IS NULL) OR (input_token_count >= 0))),
    CONSTRAINT memory_embeddings_one_source_check CHECK ((num_nonnulls(memory_node_id, memory_event_id, message_id, curated_memory_assertion_id) = 1)),
    CONSTRAINT memory_embeddings_personal_owner_check CHECK (((visibility = 'personal'::public.visibility_scope) AND (owner_user_id IS NOT NULL))),
    CONSTRAINT memory_embeddings_queryable_vector_strategy_check CHECK ((queryable_vector_strategy = 'trusted_backend_pgvector_v1'::text)),
    CONSTRAINT memory_embeddings_search_boundary_check CHECK ((search_boundary = 'owner_user_dynamic_grants'::text)),
    CONSTRAINT memory_embeddings_source_chunk_count_check CHECK (((source_chunk_count >= 1) AND (source_chunk_index < source_chunk_count))),
    CONSTRAINT memory_embeddings_source_chunk_index_check CHECK ((source_chunk_index >= 0))
);


