    CONSTRAINT memory_questions_search_domain_check CHECK (((search_domain = 'global'::public.memory_search_domain) OR ((search_domain = 'project'::public.memory_search_domain) AND (project_id IS NOT NULL)) OR ((search_domain = 'session'::public.memory_search_domain) AND (session_id IS NOT NULL)))),
    CONSTRAINT memory_questions_status_check CHECK ((((status = 'pending'::public.memory_question_status) AND (answer_markdown IS NULL) AND (error_message IS NULL) AND (answered_at IS NULL)) OR ((status = 'answered'::public.memory_question_status) AND (answer_markdown IS NOT NULL) AND (error_message IS NULL) AND (answered_at IS NOT NULL)) OR ((status = 'error'::public.memory_question_status) AND (answer_markdown IS NULL) AND (error_message IS NOT NULL) AND (answered_at IS NOT NULL))))
);


