    CONSTRAINT memory_replicas_freshness_status_check CHECK ((freshness_status = ANY (ARRAY['unknown'::text, 'fresh'::text, 'stale'::text, 'revoked'::text, 'failed'::text]))),
    CONSTRAINT memory_replicas_lifecycle_check CHECK ((((lifecycle = ANY (ARRAY['active'::public.memory_replica_lifecycle, 'stale'::public.memory_replica_lifecycle, 'revoked'::public.memory_replica_lifecycle])) AND (purge_completed_at IS NULL)) OR ((lifecycle = ANY (ARRAY['tombstoned'::public.memory_replica_lifecycle, 'purge_pending'::public.memory_replica_lifecycle])) AND (tombstoned_at IS NOT NULL) AND (purge_completed_at IS NULL)) OR ((lifecycle = 'purged'::public.memory_replica_lifecycle) AND (tombstoned_at IS NOT NULL) AND (purge_completed_at IS NOT NULL)))),
    CONSTRAINT memory_replicas_owner_version_check CHECK (((owner_principal_id IS NOT NULL) AND (version > 0) AND (latest_revision >= 0))),
    CONSTRAINT memory_replicas_policy_revision_check CHECK ((((representation_policy_revision IS NULL) AND (content_policy_version IS NULL)) OR ((representation_policy_revision > 0) AND (content_policy_version > 0))))
);


