--
-- Name: pending_share_operations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pending_share_operations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    mutation_id uuid NOT NULL,
    request_hash text NOT NULL,
    logical_grant_id uuid NOT NULL,
    consent_id uuid NOT NULL,
    authority_source text NOT NULL,
    authority_reference_id uuid NOT NULL,
    preview_id uuid NOT NULL,
    preview_hash text NOT NULL,
    preview_revision integer NOT NULL,
    display_title text,
    owner_user_id uuid NOT NULL,
    logical_memory_id uuid NOT NULL,
    team_id uuid NOT NULL,
    team_workspace_id uuid NOT NULL,
    representation public.shared_memory_representation NOT NULL,
    mode public.shared_memory_consent_mode NOT NULL,
    source_revision bigint NOT NULL,
    source_hash text NOT NULL,
    state text DEFAULT 'preparing'::text NOT NULL,
    stage text DEFAULT 'accepted'::text NOT NULL,
    workspace_access_state text DEFAULT 'none'::text NOT NULL,
    source_update_state text DEFAULT 'preparing'::text NOT NULL,
    operation_version integer DEFAULT 1 NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_control_mutation_id uuid,
    last_control_action text,
    redacted_failure_code text,
    last_progress_at timestamp with time zone DEFAULT now() NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    share_expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    activated_at timestamp with time zone,
    revoked_at timestamp with time zone,
    grant_id uuid,
    replacement_mutation_id uuid,
    replacement_request_hash text,
    replacement_consent_id uuid,
    replacement_authority_source text,
    replacement_authority_reference_id uuid,
    replacement_preview_id uuid,
    replacement_preview_hash text,
    replacement_preview_revision integer,
    replacement_representation public.shared_memory_representation,
    replacement_mode public.shared_memory_consent_mode,
    replacement_source_revision bigint,
    replacement_source_hash text,
    replacement_expires_at timestamp with time zone,
    replacement_expected_grant_version integer,
    maximum_fidelity public.shared_memory_representation NOT NULL,
    include_curated_memory boolean NOT NULL,
    replacement_maximum_fidelity public.shared_memory_representation,
    replacement_include_curated_memory boolean,
    source_revision_id uuid NOT NULL,
    source_capabilities public.shared_memory_representation[] NOT NULL,
    activation_representation public.shared_memory_representation NOT NULL,
    replacement_source_revision_id uuid,
    reviewed_grant_version integer,
    CONSTRAINT pending_share_operations_replacement_values_check CHECK ((((replacement_mutation_id IS NULL) AND (replacement_request_hash IS NULL) AND (replacement_consent_id IS NULL) AND (replacement_authority_source IS NULL) AND (replacement_authority_reference_id IS NULL) AND (replacement_preview_id IS NULL) AND (replacement_preview_hash IS NULL) AND (replacement_preview_revision IS NULL) AND (replacement_representation IS NULL) AND (replacement_maximum_fidelity IS NULL) AND (replacement_include_curated_memory IS NULL) AND (replacement_mode IS NULL) AND (replacement_source_revision_id IS NULL) AND (replacement_source_revision IS NULL) AND (replacement_source_hash IS NULL) AND (replacement_expected_grant_version IS NULL)) OR ((replacement_mutation_id IS NOT NULL) AND (length(replacement_request_hash) = 64) AND (replacement_consent_id IS NOT NULL) AND (replacement_authority_source = ANY (ARRAY['browser_session'::text, 'device_action_grant'::text, 'continuous_consent'::text])) AND (replacement_authority_reference_id IS NOT NULL) AND (replacement_preview_id IS NOT NULL) AND (length(replacement_preview_hash) = 64) AND (replacement_preview_revision > 0) AND (replacement_representation IS NOT NULL) AND (replacement_maximum_fidelity IS NOT NULL) AND (replacement_include_curated_memory IS NOT NULL) AND (replacement_mode IS NOT NULL) AND (replacement_source_revision_id IS NOT NULL) AND (replacement_source_revision >= 0) AND (length(replacement_source_hash) = 64) AND (replacement_expected_grant_version > 0)))),
    CONSTRAINT pending_share_operations_source_binding_check CHECK (((cardinality(source_capabilities) > 0) AND (activation_representation = ANY (source_capabilities)) AND (((activation_representation = 'memory_events'::public.shared_memory_representation) AND (maximum_fidelity = 'memory_events'::public.shared_memory_representation)) OR ((activation_representation = 'lcm_leaves'::public.shared_memory_representation) AND (maximum_fidelity = ANY (ARRAY['memory_events'::public.shared_memory_representation, 'lcm_leaves'::public.shared_memory_representation]))) OR (activation_representation = 'lcm_rollups'::public.shared_memory_representation) OR (((activation_representation)::text = 'curated_assertions'::text) AND (include_curated_memory = true))))),
    CONSTRAINT pending_share_operations_state_check CHECK (((state = ANY (ARRAY['preparing'::text, 'needs_attention'::text, 'failed'::text, 'activated'::text, 'revoked'::text])) AND (stage = ANY (ARRAY['accepted'::text, 'syncing'::text, 'uploading'::text, 'processing'::text, 'activating'::text, 'privacy_filtering'::text, 'complete'::text])) AND (workspace_access_state = ANY (ARRAY['none'::text, 'active'::text, 'revoked'::text])) AND (source_update_state = ANY (ARRAY['preparing'::text, 'active'::text, 'paused'::text, 'failed'::text, 'stopped'::text])))),
    CONSTRAINT pending_share_operations_values_check CHECK (((preview_revision > 0) AND (source_revision >= 0) AND (operation_version > 0) AND (attempt_count >= 0) AND (authority_source = ANY (ARRAY['browser_session'::text, 'device_action_grant'::text, 'sharing_rule'::text])) AND (((last_control_mutation_id IS NULL) AND (last_control_action IS NULL)) OR ((last_control_mutation_id IS NOT NULL) AND (last_control_action = ANY (ARRAY['retry'::text, 'pause'::text, 'resume'::text, 'revoke'::text, 'stop_direct'::text])))) AND (length(request_hash) = 64) AND (length(preview_hash) = 64) AND (length(source_hash) = 64))),
    CONSTRAINT pending_share_reviewed_grant_version_check CHECK (((reviewed_grant_version IS NULL) OR (reviewed_grant_version > 0)))
);


--
-- Name: pending_share_operation_records; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pending_share_operation_records AS
 SELECT pending.id,
    pending.mutation_id,
    pending.request_hash,
    pending.logical_grant_id,
    pending.consent_id,
    pending.authority_source,
    pending.authority_reference_id,
    pending.preview_id,
    pending.preview_hash,
    pending.preview_revision,
    pending.display_title,
    pending.owner_user_id,
    pending.logical_memory_id,
    pending.team_id,
    pending.team_workspace_id,
    pending.representation,
    pending.mode,
    pending.source_revision,
    pending.source_hash,
    pending.state,
    pending.stage,
    pending.workspace_access_state,
    pending.source_update_state,
    pending.operation_version,
    pending.attempt_count,
    pending.last_control_mutation_id,
    pending.last_control_action,
    pending.redacted_failure_code,
    pending.last_progress_at,
    pending.next_attempt_at,
    pending.share_expires_at,
    pending.created_at,
    pending.updated_at,
    pending.activated_at,
    pending.revoked_at,
    pending.grant_id,
    pending.replacement_mutation_id,
    pending.replacement_request_hash,
    pending.replacement_consent_id,
    pending.replacement_authority_source,
    pending.replacement_authority_reference_id,
    pending.replacement_preview_id,
    pending.replacement_preview_hash,
    pending.replacement_preview_revision,
    pending.replacement_representation,
    pending.replacement_mode,
    pending.replacement_source_revision,
    pending.replacement_source_hash,
    pending.replacement_expires_at,
    pending.replacement_expected_grant_version,
    pending.maximum_fidelity,
    pending.include_curated_memory,
    pending.replacement_maximum_fidelity,
    pending.replacement_include_curated_memory,
    pending.source_revision_id,
    pending.source_capabilities,
    pending.activation_representation,
    pending.replacement_source_revision_id,
    binding.source_kind,
    binding.source_session_id,
    binding.source_note_id,
    binding.source_memory_event_id
   FROM (public.pending_share_operations pending
     JOIN public.logical_memory_source_revision_bindings binding ON ((binding.source_revision_id = pending.source_revision_id)));


