    CONSTRAINT pending_rule_portable_source_check CHECK (((portable_source_hash IS NULL) OR ((admission_kind = 'conversation_create'::text) AND (portable_source_hash ~ '^[a-f0-9]{64}$'::text)))),
    CONSTRAINT pending_sharing_rule_admission_check CHECK ((((admission_kind = 'conversation_create'::text) AND (membership_id IS NULL) AND (expected_authority_version IS NULL) AND (expected_membership_version IS NULL) AND (publisher_fence IS NULL) AND (membership_request_hash IS NULL)) OR ((admission_kind = 'repository_member'::text) AND (membership_id IS NOT NULL) AND (expected_authority_version IS NOT NULL) AND (expected_authority_version > 0) AND (expected_membership_version IS NOT NULL) AND (expected_membership_version > 0) AND (publisher_fence IS NOT NULL) AND (publisher_fence > 0) AND (membership_request_hash IS NOT NULL) AND (membership_request_hash ~ '^[a-f0-9]{64}$'::text)))),
    CONSTRAINT pending_snapshot_conversion_check CHECK (((snapshot_conversion IS NULL) OR ((admission_kind = 'conversation_create'::text) AND (jsonb_typeof(snapshot_conversion) = 'object'::text))))
);


