    share_grant_id uuid,
    thread_id uuid,
    owner_private_replica_id uuid,
    logical_memory_id uuid,
    retention_seconds bigint NOT NULL,
    deletion_grace_seconds bigint DEFAULT 0 NOT NULL,
    backup_retention_seconds bigint DEFAULT 0 NOT NULL,
    policy_hash text NOT NULL,
    created_by_user_id uuid,
    effective_at timestamp with time zone NOT NULL,
    superseded_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT retention_policies_scope_check CHECK ((((scope = 'team'::public.retention_policy_scope) AND (team_id IS NOT NULL) AND (team_workspace_id IS NULL) AND (share_grant_id IS NULL) AND (thread_id IS NULL) AND (owner_private_replica_id IS NULL) AND (logical_memory_id IS NULL)) OR ((scope = 'workspace'::public.retention_policy_scope) AND (team_id IS NOT NULL) AND (team_workspace_id IS NOT NULL) AND (share_grant_id IS NULL) AND (thread_id IS NULL) AND (owner_private_replica_id IS NULL) AND (logical_memory_id IS NULL)) OR ((scope = 'share_grant'::public.retention_policy_scope) AND (team_id IS NOT NULL) AND (team_workspace_id IS NOT NULL) AND (share_grant_id IS NOT NULL) AND (thread_id IS NULL) AND (owner_private_replica_id IS NULL) AND (logical_memory_id IS NOT NULL)) OR ((scope = 'thread'::public.retention_policy_scope) AND (team_id IS NOT NULL) AND (share_grant_id IS NULL) AND (thread_id IS NOT NULL) AND (owner_private_replica_id IS NULL) AND (logical_memory_id IS NULL)) OR ((scope = 'owner_private_replica'::public.retention_policy_scope) AND (team_id IS NULL) AND (team_workspace_id IS NULL) AND (share_grant_id IS NULL) AND (thread_id IS NULL) AND (owner_private_replica_id IS NOT NULL) AND (logical_memory_id IS NOT NULL)))),
    CONSTRAINT retention_policies_values_check CHECK (((version > 0) AND (retention_seconds >= 0) AND (deletion_grace_seconds >= 0) AND (backup_retention_seconds >= 0) AND (length(policy_hash) = 64) AND ((superseded_at IS NULL) OR (superseded_at > effective_at))))
);


