    CONSTRAINT retention_policy_shortening_previews_lifecycle_check CHECK ((((state = 'pending'::public.retention_policy_shortening_state) AND (confirmed_by_user_id IS NULL) AND (confirmed_at IS NULL) AND (invalidated_at IS NULL) AND (invalidation_reason_code IS NULL)) OR ((state = 'confirmed'::public.retention_policy_shortening_state) AND (confirmed_by_user_id IS NOT NULL) AND (confirmed_at >= grace_until) AND (invalidated_at IS NULL) AND (invalidation_reason_code IS NULL)) OR ((state = 'invalidated'::public.retention_policy_shortening_state) AND (confirmed_by_user_id IS NULL) AND (confirmed_at IS NULL) AND (invalidated_at IS NOT NULL) AND (length(TRIM(BOTH FROM invalidation_reason_code)) > 0)))),
    CONSTRAINT retention_policy_shortening_previews_values_check CHECK (((policy_version > 0) AND (affected_scope_count >= 0) AND (length(policy_hash) = 64) AND (length(preview_hash) = 64) AND (grace_until > previewed_at)))
);


