--
-- Name: shared_memory_candidate_previews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.shared_memory_candidate_previews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    preview_hash text NOT NULL,
    preview_revision integer DEFAULT 1 NOT NULL,
    authority_source text NOT NULL,
    authority_reference_id uuid NOT NULL,
    owner_user_id uuid NOT NULL,
    logical_memory_id uuid NOT NULL,
    team_id uuid NOT NULL,
    team_workspace_id uuid NOT NULL,
    representation public.shared_memory_representation NOT NULL,
    mode public.shared_memory_consent_mode NOT NULL,
    source_revision bigint NOT NULL,
    source_hash text NOT NULL,
    redacted_content_hash text NOT NULL,
    item_count integer NOT NULL,
    excluded_item_count integer DEFAULT 0 NOT NULL,
    candidate_manifest jsonb NOT NULL,
    candidate_manifest_hash text NOT NULL,
    byte_count integer NOT NULL,
    representation_policy_revision integer NOT NULL,
    representation_policy_hash text NOT NULL,
    content_policy_version integer NOT NULL,
    content_policy_hash text NOT NULL,
    classifier_version integer NOT NULL,
    classifier_hash text NOT NULL,
    share_expires_at timestamp with time zone,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    invalidated_at timestamp with time zone,
    invalidation_reason text,
    maximum_fidelity public.shared_memory_representation NOT NULL,
    include_curated_memory boolean NOT NULL,
    source_revision_id uuid NOT NULL,
    source_capabilities public.shared_memory_representation[] NOT NULL,
    activation_representation public.shared_memory_representation NOT NULL,
    CONSTRAINT shared_memory_candidate_previews_hashes_check CHECK (((length(preview_hash) = 64) AND (length(candidate_manifest_hash) = 64) AND (length(source_hash) = 64) AND (length(redacted_content_hash) = 64) AND (length(representation_policy_hash) = 64) AND (length(content_policy_hash) = 64) AND (length(classifier_hash) = 64))),
    CONSTRAINT shared_memory_candidate_previews_source_binding_check CHECK (((cardinality(source_capabilities) > 0) AND (activation_representation = ANY (source_capabilities)) AND (((activation_representation = 'memory_events'::public.shared_memory_representation) AND (maximum_fidelity = 'memory_events'::public.shared_memory_representation)) OR ((activation_representation = 'lcm_leaves'::public.shared_memory_representation) AND (maximum_fidelity = ANY (ARRAY['memory_events'::public.shared_memory_representation, 'lcm_leaves'::public.shared_memory_representation]))) OR (activation_representation = 'lcm_rollups'::public.shared_memory_representation) OR (((activation_representation)::text = 'curated_assertions'::text) AND (include_curated_memory = true))))),
    CONSTRAINT shared_memory_candidate_previews_values_check CHECK (((preview_revision = 1) AND (authority_source = ANY (ARRAY['browser_session'::text, 'device_action_grant'::text, 'continuous_consent'::text, 'sharing_rule'::text])) AND (source_revision >= 0) AND ((item_count >= 1) AND (item_count <= 100)) AND (excluded_item_count >= 0) AND (jsonb_typeof(candidate_manifest) = 'array'::text) AND (jsonb_array_length(candidate_manifest) = item_count) AND ((byte_count >= 1) AND (byte_count <= 262144)) AND (representation_policy_revision > 0) AND (content_policy_version > 0) AND (classifier_version > 0) AND (expires_at > created_at)))
);


