    candidate.redacted_content_hash,
    candidate.item_count,
    candidate.excluded_item_count,
    candidate.candidate_manifest,
    candidate.candidate_manifest_hash,
    candidate.byte_count,
    candidate.representation_policy_revision,
    candidate.representation_policy_hash,
    candidate.content_policy_version,
    candidate.content_policy_hash,
    candidate.classifier_version,
    candidate.classifier_hash,
