    continuation_chunk_index integer DEFAULT 0 NOT NULL,
    CONSTRAINT shared_source_semantic_previews_hash_check CHECK (((source_preview_hash ~ '^[0-9a-f]{64}$'::text) AND (source_artifact_hash ~ '^[0-9a-f]{64}$'::text) AND (source_manifest_hash ~ '^[0-9a-f]{64}$'::text) AND (source_hash ~ '^[0-9a-f]{64}$'::text) AND (classifier_hash ~ '^[0-9a-f]{64}$'::text) AND (effective_privacy_policy_hash ~ '^[0-9a-f]{64}$'::text) AND ((expected_manifest_hash IS NULL) OR (expected_manifest_hash ~ '^[0-9a-f]{64}$'::text)) AND ((result_manifest_hash IS NULL) OR (result_manifest_hash ~ '^[0-9a-f]{64}$'::text)) AND ((source_item_identity_hash IS NULL) OR (source_item_identity_hash ~ '^[0-9a-f]{64}$'::text)) AND ((sanitized_content_hash IS NULL) OR (sanitized_content_hash ~ '^[0-9a-f]{64}$'::text)) AND ((payload_binding_hash IS NULL) OR (payload_binding_hash ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT shared_source_semantic_previews_item_count_check CHECK (((source_item_count IS NULL) OR ((source_item_count >= 1) AND (source_item_count <= 2048)))),
    CONSTRAINT shared_source_semantic_previews_lifecycle_check CHECK ((((status = 'pending'::text) AND (result_manifest_hash IS NULL) AND (sanitized_content_hash IS NULL) AND (payload_binding_hash IS NULL) AND (failure_code IS NULL) AND (ready_at IS NULL) AND (failed_at IS NULL) AND (stale_at IS NULL) AND (invalidated_at IS NULL) AND (invalidation_reason_code IS NULL)) OR ((status = 'ready'::text) AND (expected_manifest_hash IS NOT NULL) AND (expected_chunk_count IS NOT NULL) AND (completed_chunk_count = expected_chunk_count) AND (result_manifest_hash IS NOT NULL) AND (classification_field_count IS NOT NULL) AND (classification_byte_count IS NOT NULL) AND (source_item_identity_hash IS NOT NULL) AND (source_item_count IS NOT NULL) AND (sanitized_content_hash IS NOT NULL) AND (payload_binding_hash IS NOT NULL) AND (failure_code IS NULL) AND (ready_at IS NOT NULL) AND (failed_at IS NULL) AND (stale_at IS NULL) AND (invalidated_at IS NULL) AND (invalidation_reason_code IS NULL)) OR ((status = 'failed'::text) AND (result_manifest_hash IS NULL) AND (source_item_identity_hash IS NOT NULL) AND (source_item_count IS NOT NULL) AND (sanitized_content_hash IS NULL) AND (payload_binding_hash IS NULL) AND (length(TRIM(BOTH FROM failure_code)) > 0) AND (ready_at IS NULL) AND (failed_at IS NOT NULL) AND (stale_at IS NULL) AND (invalidated_at IS NULL) AND (invalidation_reason_code IS NULL)) OR ((status = 'stale'::text) AND (expected_manifest_hash IS NOT NULL) AND (result_manifest_hash IS NOT NULL) AND (source_item_identity_hash IS NOT NULL) AND (source_item_count IS NOT NULL) AND (sanitized_content_hash IS NOT NULL) AND (payload_binding_hash IS NOT NULL) AND (failure_code IS NULL) AND (ready_at IS NOT NULL) AND (failed_at IS NULL) AND (stale_at IS NOT NULL) AND (invalidated_at IS NULL) AND (length(TRIM(BOTH FROM invalidation_reason_code)) > 0)) OR ((status = 'invalidated'::text) AND (invalidated_at IS NOT NULL) AND (length(TRIM(BOTH FROM invalidation_reason_code)) > 0)))),
    CONSTRAINT shared_source_semantic_previews_retry_check CHECK (((attempt_count >= 0) AND (((attempt_count = 0) AND (next_attempt_at IS NULL) AND (last_error_class IS NULL)) OR ((attempt_count > 0) AND (status = 'pending'::text) AND (next_attempt_at IS NOT NULL) AND (length(TRIM(BOTH FROM last_error_class)) > 0))))),
    CONSTRAINT shared_source_semantic_previews_revision_check CHECK (((source_preview_revision > 0) AND (source_revision >= 0) AND (classifier_version > 0))),
    CONSTRAINT shared_source_semantic_previews_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'ready'::text, 'failed'::text, 'stale'::text, 'invalidated'::text]))),
    CONSTRAINT shared_source_semantic_previews_work_check CHECK (((scheduling_class = ANY (ARRAY['foreground'::text, 'background'::text])) AND (work_reason = ANY (ARRAY['share_activation'::text, 'source_revision_classification'::text, 'policy_remasking'::text, 'classifier_rematerialization'::text, 'background_repair'::text])) AND (continuation_chunk_index >= 0) AND (completed_chunk_count >= 0) AND ((expected_chunk_count IS NULL) OR (expected_chunk_count > 0)) AND ((classification_field_count IS NULL) OR (classification_field_count > 0)) AND ((classification_byte_count IS NULL) OR (classification_byte_count >= 0)) AND ((expected_chunk_count IS NULL) OR (completed_chunk_count <= expected_chunk_count))))
);


