    CONSTRAINT shared_source_semantic_privacy_work_claims_generation_check CHECK (((claim_generation > 0) AND ((length(TRIM(BOTH FROM claimant_id)) >= 1) AND (length(TRIM(BOTH FROM claimant_id)) <= 200)))),
    CONSTRAINT shared_source_semantic_privacy_work_claims_hash_check CHECK ((work_identity ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT shared_source_semantic_privacy_work_claims_lifecycle_check CHECK ((((state = 'active'::text) AND (released_at IS NULL) AND (completed_at IS NULL)) OR ((state = 'released'::text) AND (released_at IS NOT NULL) AND (completed_at IS NULL)) OR ((state = 'completed'::text) AND (completed_at IS NOT NULL))))
);


--
-- Name: source_owner_representation_consents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.source_owner_representation_consents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    logical_memory_id uuid NOT NULL,
    remote_replica_id uuid,
    source_owner_principal_id uuid NOT NULL,
    team_id uuid NOT NULL,
    team_workspace_id uuid NOT NULL,
    source_owner_policy_id uuid NOT NULL,
    source_owner_policy_version integer NOT NULL,
    team_policy_id uuid NOT NULL,
    team_policy_version integer NOT NULL,
    workspace_policy_id uuid NOT NULL,
    workspace_policy_version integer NOT NULL,
    mode public.shared_memory_consent_mode NOT NULL,
    state public.shared_memory_consent_state DEFAULT 'pending'::public.shared_memory_consent_state NOT NULL,
    consent_version integer DEFAULT 1 NOT NULL,
    preview_id uuid NOT NULL,
    preview_revision integer NOT NULL,
    preview_hash text NOT NULL,
    source_revision bigint NOT NULL,
    maximum_authorized_source_revision bigint,
    source_hash text NOT NULL,
    content_policy_version integer NOT NULL,
    content_policy_hash text NOT NULL,
    classifier_version integer NOT NULL,
    classifier_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    activated_at timestamp with time zone,
    paused_at timestamp with time zone,
    revoked_at timestamp with time zone,
    expires_at timestamp with time zone,
    state_reason_code text,
    maximum_fidelity public.shared_memory_representation NOT NULL,
    include_curated_memory boolean DEFAULT false NOT NULL,
    fidelity_policy_revision integer NOT NULL,
    fidelity_policy_hash text NOT NULL,
    source_content_hash text NOT NULL,
    source_revision_id uuid NOT NULL,
    source_capabilities public.shared_memory_representation[] NOT NULL,
    activation_representation public.shared_memory_representation NOT NULL,
    CONSTRAINT source_owner_consents_fidelity_check CHECK ((maximum_fidelity = ANY (ARRAY['memory_events'::public.shared_memory_representation, 'lcm_leaves'::public.shared_memory_representation, 'lcm_rollups'::public.shared_memory_representation]))),
    CONSTRAINT source_owner_consents_hash_check CHECK (((length(preview_hash) = 64) AND (length(source_hash) = 64) AND (length(fidelity_policy_hash) = 64) AND (length(content_policy_hash) = 64) AND (length(classifier_hash) = 64) AND (length(source_content_hash) = 64))),
    CONSTRAINT source_owner_consents_lifecycle_check CHECK ((((state = 'pending'::public.shared_memory_consent_state) AND (activated_at IS NULL) AND (paused_at IS NULL) AND (revoked_at IS NULL)) OR ((state = 'active'::public.shared_memory_consent_state) AND (activated_at IS NOT NULL) AND (paused_at IS NULL) AND (revoked_at IS NULL)) OR ((state = 'paused'::public.shared_memory_consent_state) AND (activated_at IS NOT NULL) AND (paused_at IS NOT NULL) AND (revoked_at IS NULL)) OR ((state = 'revoked'::public.shared_memory_consent_state) AND (revoked_at IS NOT NULL)) OR ((state = 'expired'::public.shared_memory_consent_state) AND (revoked_at IS NULL) AND (expires_at IS NOT NULL)))),
    CONSTRAINT source_owner_consents_mode_check CHECK ((((mode = 'snapshot'::public.shared_memory_consent_mode) AND (maximum_authorized_source_revision = source_revision)) OR ((mode = 'continuous'::public.shared_memory_consent_mode) AND (maximum_authorized_source_revision IS NULL)))),
    CONSTRAINT source_owner_consents_revision_check CHECK (((preview_revision > 0) AND (source_revision >= 0) AND (fidelity_policy_revision > 0) AND (content_policy_version > 0) AND (classifier_version > 0) AND (source_owner_policy_version > 0) AND (team_policy_version > 0) AND (workspace_policy_version > 0))),
    CONSTRAINT source_owner_consents_source_binding_check CHECK (((cardinality(source_capabilities) > 0) AND (activation_representation = ANY (source_capabilities)) AND (((activation_representation = 'memory_events'::public.shared_memory_representation) AND (maximum_fidelity = 'memory_events'::public.shared_memory_representation)) OR ((activation_representation = 'lcm_leaves'::public.shared_memory_representation) AND (maximum_fidelity = ANY (ARRAY['memory_events'::public.shared_memory_representation, 'lcm_leaves'::public.shared_memory_representation]))) OR (activation_representation = 'lcm_rollups'::public.shared_memory_representation) OR (((activation_representation)::text = 'curated_assertions'::text) AND (include_curated_memory = true))))),
    CONSTRAINT source_owner_consents_version_check CHECK ((consent_version > 0))
);


--
-- Name: source_owner_representation_consent_records; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.source_owner_representation_consent_records AS
 SELECT consent.id,
    consent.logical_memory_id,
    consent.remote_replica_id,
    consent.source_owner_principal_id,
    consent.team_id,
    consent.team_workspace_id,
    consent.source_owner_policy_id,
    consent.source_owner_policy_version,
    consent.team_policy_id,
    consent.team_policy_version,
    consent.workspace_policy_id,
    consent.workspace_policy_version,
    consent.mode,
    consent.state,
    consent.consent_version,
    consent.preview_id,
    consent.preview_revision,
    consent.preview_hash,
    consent.source_revision,
    consent.maximum_authorized_source_revision,
    consent.source_hash,
    consent.content_policy_version,
    consent.content_policy_hash,
    consent.classifier_version,
    consent.classifier_hash,
    consent.created_at,
    consent.updated_at,
    consent.activated_at,
    consent.paused_at,
    consent.revoked_at,
    consent.expires_at,
    consent.state_reason_code,
    consent.maximum_fidelity,
    consent.include_curated_memory,
    consent.fidelity_policy_revision,
    consent.fidelity_policy_hash,
    consent.source_content_hash,
    consent.source_revision_id,
    consent.source_capabilities,
    consent.activation_representation,
    binding.source_kind,
    binding.source_session_id,
    binding.source_note_id,
    binding.source_memory_event_id
   FROM (public.source_owner_representation_consents consent
     JOIN public.logical_memory_source_revision_bindings binding ON ((binding.source_revision_id = consent.source_revision_id)));


