    CONSTRAINT team_conversation_source_grants_lifecycle_check CHECK ((((lifecycle = 'active'::text) AND (revoked_at IS NULL) AND (revoked_by_user_id IS NULL) AND (revocation_reason IS NULL)) OR ((lifecycle = 'revoked'::text) AND (revoked_at IS NOT NULL) AND (revoked_by_user_id IS NOT NULL) AND ((length(TRIM(BOTH FROM revocation_reason)) >= 1) AND (length(TRIM(BOTH FROM revocation_reason)) <= 120))))),
    CONSTRAINT team_conversation_source_grants_mode_check CHECK ((((mode = 'continuous'::text) AND (maximum_segment_index IS NULL) AND (maximum_source_offset IS NULL)) OR ((mode = 'snapshot'::text) AND (maximum_segment_index >= 0) AND (maximum_source_offset >= 0)))),
    CONSTRAINT team_conversation_source_grants_version_check CHECK (((version > 0) AND (length(TRIM(BOTH FROM creator_authority)) > 0)))
);


--
-- Name: team_invites; Type: TABLE; Schema: public; Owner: -
