    default_workspace_access public.team_workspace_access DEFAULT 'write'::public.team_workspace_access NOT NULL,
    normalized_email text,
    backend_origin_hash text,
    version integer DEFAULT 1 NOT NULL,
    lifecycle public.invite_lifecycle DEFAULT 'pending'::public.invite_lifecycle NOT NULL,
    CONSTRAINT team_invites_binding_check CHECK (((default_team_workspace_id IS NOT NULL) AND (normalized_email IS NOT NULL) AND (length(TRIM(BOTH FROM normalized_email)) > 0) AND (normalized_email = lower(TRIM(BOTH FROM email))) AND (backend_origin_hash IS NOT NULL) AND (length(backend_origin_hash) = 64) AND (default_workspace_access = ANY (ARRAY['read'::public.team_workspace_access, 'write'::public.team_workspace_access])))),
    CONSTRAINT team_invites_lifecycle_shape_check CHECK ((((lifecycle = 'pending'::public.invite_lifecycle) AND (accepted_at IS NULL) AND (revoked_at IS NULL)) OR ((lifecycle = 'accepted'::public.invite_lifecycle) AND (accepted_at IS NOT NULL) AND (revoked_at IS NULL)) OR ((lifecycle = 'revoked'::public.invite_lifecycle) AND (accepted_at IS NULL) AND (revoked_at IS NOT NULL)) OR ((lifecycle = 'expired'::public.invite_lifecycle) AND (accepted_at IS NULL) AND (revoked_at IS NULL)))),
    CONSTRAINT team_invites_token_hash_length_check CHECK ((length(token_hash) >= 32)),
    CONSTRAINT team_invites_version_check CHECK ((version > 0))
);


