);


--
-- Name: team_memory_representations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.team_memory_representations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    share_grant_id uuid NOT NULL,
    consent_id uuid NOT NULL,
    source_preview_id uuid NOT NULL,
    source_artifact_id uuid NOT NULL,
    team_id uuid NOT NULL,
    team_workspace_id uuid NOT NULL,
    logical_memory_id uuid NOT NULL,
    representation public.shared_memory_representation NOT NULL,
    source_revision bigint NOT NULL,
    source_revision_hash text NOT NULL,
    provenance_hash text NOT NULL,
    source_owner_policy_id uuid NOT NULL,
    source_owner_policy_version integer NOT NULL,
    team_policy_id uuid NOT NULL,
    team_policy_version integer NOT NULL,
    workspace_policy_id uuid NOT NULL,
    workspace_policy_version integer NOT NULL,
    content_policy_version integer NOT NULL,
    classifier_version integer NOT NULL,
    record_version integer DEFAULT 1 NOT NULL,
    state public.memory_representation_state DEFAULT 'pending'::public.memory_representation_state NOT NULL,
    chunk_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    freshness_evaluated_at timestamp with time zone,
    available_at timestamp with time zone,
    stale_at timestamp with time zone,
    invalidated_at timestamp with time zone,
    invalidation_reason_code text,
    tombstoned_at timestamp with time zone,
    retain_until timestamp with time zone,
    purge_completed_at timestamp with time zone,
    curated_expires_at timestamp with time zone,
    sanitized_source_preview_id uuid NOT NULL,
    privacy_classifier_generation_id uuid NOT NULL,
    privacy_classifier_hash text NOT NULL,
    effective_privacy_policy_hash text NOT NULL,
    source_manifest_hash text NOT NULL,
    sanitized_content_hash text NOT NULL,
    fidelity_policy_revision integer NOT NULL,
    source_revision_id uuid NOT NULL,
    display_title text,
    CONSTRAINT team_memory_representations_hash_check CHECK (((length(source_revision_hash) = 64) AND (length(provenance_hash) = 64) AND (privacy_classifier_hash ~ '^[0-9a-f]{64}$'::text) AND (effective_privacy_policy_hash ~ '^[0-9a-f]{64}$'::text) AND (source_manifest_hash ~ '^[0-9a-f]{64}$'::text) AND (sanitized_content_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT team_memory_representations_lifecycle_check CHECK ((((state = 'pending'::public.memory_representation_state) AND (available_at IS NULL) AND (stale_at IS NULL) AND (invalidated_at IS NULL) AND (tombstoned_at IS NULL) AND (purge_completed_at IS NULL)) OR ((state = 'available'::public.memory_representation_state) AND (available_at IS NOT NULL) AND (stale_at IS NULL) AND (invalidated_at IS NULL) AND (tombstoned_at IS NULL) AND (purge_completed_at IS NULL)) OR ((state = 'stale'::public.memory_representation_state) AND (available_at IS NOT NULL) AND (stale_at IS NOT NULL) AND (invalidated_at IS NULL) AND (tombstoned_at IS NULL) AND (purge_completed_at IS NULL)) OR ((state = 'invalidated'::public.memory_representation_state) AND (invalidated_at IS NOT NULL) AND (tombstoned_at IS NULL) AND (purge_completed_at IS NULL)) OR ((state = 'purge_pending'::public.memory_representation_state) AND (tombstoned_at IS NOT NULL) AND (purge_completed_at IS NULL)) OR ((state = 'purged'::public.memory_representation_state) AND (tombstoned_at IS NOT NULL) AND (purge_completed_at IS NOT NULL)))),
    CONSTRAINT team_memory_representations_title_marker_check CHECK (((display_title IS NULL) OR (display_title = '[koed encrypted Shared Memory title]'::text))),
    CONSTRAINT team_memory_representations_version_check CHECK (((record_version > 0) AND (source_revision >= 0) AND (source_owner_policy_version > 0) AND (team_policy_version > 0) AND (workspace_policy_version > 0) AND (fidelity_policy_revision > 0) AND (content_policy_version > 0) AND (classifier_version > 0) AND (chunk_count >= 0)))
);


--
-- Name: team_memory_share_grants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.team_memory_share_grants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    logical_grant_id uuid DEFAULT gen_random_uuid() NOT NULL,
    logical_memory_id uuid,
    source_revision_id uuid,
    remote_replica_id uuid,
    owner_user_id uuid,
    owner_principal_id uuid,
    display_title text,
    display_title_source_revision bigint,
    team_id uuid NOT NULL,
    team_workspace_id uuid NOT NULL,
    consent_id uuid,
    source_owner_policy_id uuid,
    source_owner_policy_version integer,
    team_policy_id uuid,
    team_policy_version integer,
    workspace_policy_id uuid,
    workspace_policy_version integer,
    source_capabilities public.shared_memory_representation[] NOT NULL,
    activation_representation public.shared_memory_representation NOT NULL,
    mode public.shared_memory_consent_mode NOT NULL,
    maximum_fidelity public.shared_memory_representation,
    include_curated_memory boolean,
    fidelity_policy_revision integer,
    content_policy_version integer,
    classifier_version integer,
    source_revision bigint,
    grant_version integer DEFAULT 1 NOT NULL,
    revocation_epoch bigint DEFAULT 0 NOT NULL,
    lifecycle public.share_grant_lifecycle DEFAULT 'active'::public.share_grant_lifecycle NOT NULL,
    creator_authority text,
    granted_by_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by_user_id uuid,
    revocation_reason text,
    personal_deleted_at timestamp with time zone,
    personal_deleted_by_user_id uuid,
    personal_deletion_reason text,
    retained_by_team_at timestamp with time zone DEFAULT now(),
    retention_reason text DEFAULT 'active_team_share'::text NOT NULL,
    retention_policy_id uuid,
    retention_policy_version integer,
    retention_triggered_at timestamp with time zone,
    retain_until timestamp with time zone,
    active_retention_decision_id uuid,
    active_purge_job_id uuid,
    tombstoned_at timestamp with time zone,
    purge_completed_at timestamp with time zone,
    repository_snapshot jsonb DEFAULT '{"label": null, "version": 1, "fingerprint": null, "classification": "unresolved", "branchObservation": null}'::jsonb NOT NULL,
    repository_snapshot_source_revision bigint,
    CONSTRAINT team_memory_share_grants_active_retention_check CHECK ((((active_retention_decision_id IS NULL) AND (active_purge_job_id IS NULL)) OR ((active_retention_decision_id IS NOT NULL) AND (active_purge_job_id IS NOT NULL) AND (retention_policy_id IS NOT NULL) AND (retention_policy_version > 0) AND (retention_triggered_at IS NOT NULL) AND (retain_until IS NOT NULL)))),
    CONSTRAINT team_memory_share_grants_fidelity_check CHECK (((maximum_fidelity = ANY (ARRAY['memory_events'::public.shared_memory_representation, 'lcm_leaves'::public.shared_memory_representation, 'lcm_rollups'::public.shared_memory_representation])) AND (include_curated_memory IS NOT NULL) AND (((activation_representation = 'memory_events'::public.shared_memory_representation) AND (maximum_fidelity = 'memory_events'::public.shared_memory_representation)) OR ((activation_representation = 'lcm_leaves'::public.shared_memory_representation) AND (maximum_fidelity = ANY (ARRAY['memory_events'::public.shared_memory_representation, 'lcm_leaves'::public.shared_memory_representation]))) OR (activation_representation = 'lcm_rollups'::public.shared_memory_representation) OR (((activation_representation)::text = 'curated_assertions'::text) AND (include_curated_memory = true))) AND (fidelity_policy_revision > 0) AND (content_policy_version > 0) AND (classifier_version > 0) AND (source_revision >= 0))),
    CONSTRAINT team_memory_share_grants_identity_check CHECK (((logical_memory_id IS NOT NULL) AND (owner_principal_id IS NOT NULL) AND (source_revision_id IS NOT NULL) AND (consent_id IS NOT NULL) AND (source_owner_policy_id IS NOT NULL) AND (source_owner_policy_version > 0) AND (team_policy_id IS NOT NULL) AND (team_policy_version > 0) AND (workspace_policy_id IS NOT NULL) AND (workspace_policy_version > 0) AND (creator_authority IS NOT NULL) AND (length(TRIM(BOTH FROM creator_authority)) > 0) AND (cardinality(source_capabilities) > 0) AND (activation_representation = ANY (source_capabilities)))),
    CONSTRAINT team_memory_share_grants_retention_check CHECK ((((retention_policy_id IS NULL) AND (retention_policy_version IS NULL)) OR ((retention_policy_id IS NOT NULL) AND (retention_policy_version > 0)))),
    CONSTRAINT team_memory_share_grants_version_check CHECK (((grant_version > 0) AND (revocation_epoch >= 0)))
);


