);


--
-- Name: team_memory_reason_grant_records; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.team_memory_reason_grant_records AS
 SELECT reason_grant.id,
    reason_grant.logical_grant_id,
    reason_grant.logical_memory_id,
    reason_grant.owner_user_id,
    reason_grant.owner_principal_id,
    reason_grant.display_title,
    reason_grant.display_title_source_revision,
    reason_grant.team_id,
    reason_grant.team_workspace_id,
    reason_grant.grant_version,
    reason_grant.revocation_epoch,
    reason_grant.lifecycle,
    reason_grant.creator_authority,
    reason_grant.granted_by_user_id,
    reason_grant.created_at,
    reason_grant.updated_at,
    reason_grant.revoked_at,
    reason_grant.revoked_by_user_id,
    reason_grant.revocation_reason,
    reason_grant.personal_deleted_at,
    reason_grant.personal_deleted_by_user_id,
    reason_grant.personal_deletion_reason,
    reason_grant.retained_by_team_at,
    reason_grant.retention_reason,
    reason_grant.retention_policy_id,
    reason_grant.retention_policy_version,
    reason_grant.retention_triggered_at,
    reason_grant.retain_until,
    reason_grant.active_retention_decision_id,
    reason_grant.active_purge_job_id,
    reason_grant.tombstoned_at,
    reason_grant.purge_completed_at,
    reason_grant.sharing_reason_id,
    reason_grant.sharing_reason_kind,
    reason_grant.sharing_rule_id,
    reason_grant.consent_id,
    reason_grant.remote_replica_id,
    reason_grant.source_owner_policy_id,
    reason_grant.source_owner_policy_version,
    reason_grant.team_policy_id,
    reason_grant.team_policy_version,
    reason_grant.workspace_policy_id,
    reason_grant.workspace_policy_version,
    reason_grant.source_capabilities,
    reason_grant.activation_representation,
    reason_grant.mode,
    reason_grant.maximum_fidelity,
    reason_grant.include_curated_memory,
    reason_grant.fidelity_policy_revision,
    reason_grant.content_policy_version,
    reason_grant.classifier_version,
    reason_grant.repository_snapshot,
    reason_grant.repository_snapshot_source_revision,
    reason_grant.source_revision_id,
    reason_grant.source_revision,
    binding.source_kind,
    binding.source_session_id,
    binding.source_note_id,
    binding.source_memory_event_id
   FROM (( SELECT grant_row.id,
            grant_row.logical_grant_id,
            grant_row.logical_memory_id,
            grant_row.owner_user_id,
            grant_row.owner_principal_id,
            grant_row.display_title,
            grant_row.display_title_source_revision,
            grant_row.team_id,
            grant_row.team_workspace_id,
            grant_row.grant_version,
            grant_row.revocation_epoch,
            grant_row.lifecycle,
            grant_row.creator_authority,
            grant_row.granted_by_user_id,
            grant_row.created_at,
            grant_row.updated_at,
            grant_row.revoked_at,
            grant_row.revoked_by_user_id,
            grant_row.revocation_reason,
            grant_row.personal_deleted_at,
            grant_row.personal_deleted_by_user_id,
            grant_row.personal_deletion_reason,
            grant_row.retained_by_team_at,
            grant_row.retention_reason,
            grant_row.retention_policy_id,
            grant_row.retention_policy_version,
            grant_row.retention_triggered_at,
            grant_row.retain_until,
            grant_row.active_retention_decision_id,
            grant_row.active_purge_job_id,
            grant_row.tombstoned_at,
            grant_row.purge_completed_at,
            reason.id AS sharing_reason_id,
            reason.kind AS sharing_reason_kind,
            reason.rule_id AS sharing_rule_id,
            consent.id AS consent_id,
            consent.remote_replica_id,
            consent.source_owner_policy_id,
            consent.source_owner_policy_version,
            consent.team_policy_id,
            consent.team_policy_version,
            consent.workspace_policy_id,
            consent.workspace_policy_version,
            consent.source_capabilities,
            consent.activation_representation,
            consent.mode,
            consent.maximum_fidelity,
            consent.include_curated_memory,
            consent.fidelity_policy_revision,
            consent.content_policy_version,
            consent.classifier_version,
            reason.repository_snapshot,
            reason.repository_snapshot_source_revision,
            COALESCE(( SELECT representation.source_revision_id
                   FROM (public.team_memory_reason_publications publication
                     JOIN public.team_memory_representations representation ON ((representation.id = publication.representation_id)))
                  WHERE ((publication.reason_id = reason.id) AND (publication.consent_id = reason.consent_id) AND (representation.state = ANY (ARRAY['available'::public.memory_representation_state, 'stale'::public.memory_representation_state])) AND (representation.invalidated_at IS NULL))
                  ORDER BY representation.source_revision DESC, representation.id DESC
                 LIMIT 1), consent.source_revision_id) AS source_revision_id,
            COALESCE(( SELECT max(representation.source_revision) AS max
                   FROM (public.team_memory_reason_publications publication
                     JOIN public.team_memory_representations representation ON ((representation.id = publication.representation_id)))
                  WHERE ((publication.reason_id = reason.id) AND (publication.consent_id = reason.consent_id) AND (representation.state = ANY (ARRAY['available'::public.memory_representation_state, 'stale'::public.memory_representation_state])) AND (representation.invalidated_at IS NULL))), consent.source_revision) AS source_revision
           FROM ((public.team_memory_share_grants grant_row
             JOIN public.team_memory_share_reasons reason ON ((reason.share_grant_id = grant_row.id)))
             JOIN public.source_owner_representation_consents consent ON (((consent.id = reason.consent_id) AND (consent.logical_memory_id = grant_row.logical_memory_id) AND (consent.source_owner_principal_id = grant_row.owner_principal_id) AND (consent.team_id = grant_row.team_id) AND (consent.team_workspace_id = grant_row.team_workspace_id))))) reason_grant
     JOIN public.logical_memory_source_revision_bindings binding ON ((binding.source_revision_id = reason_grant.source_revision_id)));


--
-- Name: team_memory_publication_grant_records; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.team_memory_publication_grant_records AS
 SELECT g.id,
    g.logical_grant_id,
    g.logical_memory_id,
    g.owner_user_id,
    g.owner_principal_id,
    g.display_title,
    g.display_title_source_revision,
    g.team_id,
    g.team_workspace_id,
    g.grant_version,
    g.revocation_epoch,
    g.lifecycle,
    g.creator_authority,
    g.granted_by_user_id,
    g.created_at,
    g.updated_at,
    g.revoked_at,
    g.revoked_by_user_id,
    g.revocation_reason,
    g.personal_deleted_at,
    g.personal_deleted_by_user_id,
    g.personal_deletion_reason,
    g.retained_by_team_at,
    g.retention_reason,
    g.retention_policy_id,
    g.retention_policy_version,
    g.retention_triggered_at,
    g.retain_until,
    g.active_retention_decision_id,
    g.active_purge_job_id,
    g.tombstoned_at,
    g.purge_completed_at,
    g.sharing_reason_id,
    g.sharing_reason_kind,
    g.sharing_rule_id,
    g.consent_id,
    g.remote_replica_id,
    g.source_capabilities,
    g.activation_representation,
    g.mode,
    g.maximum_fidelity,
    g.include_curated_memory,
    g.repository_snapshot,
    g.repository_snapshot_source_revision,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN r.source_revision_id
            ELSE g.source_revision_id
        END AS source_revision_id,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN r.source_revision
            ELSE g.source_revision
        END AS source_revision,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN r.source_owner_policy_id
            ELSE g.source_owner_policy_id
        END AS source_owner_policy_id,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN r.source_owner_policy_version
            ELSE g.source_owner_policy_version
        END AS source_owner_policy_version,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN r.team_policy_id
            ELSE g.team_policy_id
        END AS team_policy_id,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN r.team_policy_version
            ELSE g.team_policy_version
        END AS team_policy_version,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN r.workspace_policy_id
            ELSE g.workspace_policy_id
        END AS workspace_policy_id,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN r.workspace_policy_version
            ELSE g.workspace_policy_version
        END AS workspace_policy_version,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN r.fidelity_policy_revision
            ELSE g.fidelity_policy_revision
        END AS fidelity_policy_revision,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN r.content_policy_version
            ELSE g.content_policy_version
        END AS content_policy_version,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN r.classifier_version
            ELSE g.classifier_version
        END AS classifier_version,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN source_binding.source_kind
            ELSE g.source_kind
        END AS source_kind,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN source_binding.source_session_id
            ELSE g.source_session_id
        END AS source_session_id,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN source_binding.source_note_id
            ELSE g.source_note_id
        END AS source_note_id,
        CASE
            WHEN (g.sharing_reason_kind = 'rule'::text) THEN source_binding.source_memory_event_id
            ELSE g.source_memory_event_id
        END AS source_memory_event_id,
    r.id AS publication_representation_id
   FROM (((public.team_memory_reason_grant_records g
     JOIN public.team_memory_reason_publications publication ON (((publication.reason_id = g.sharing_reason_id) AND (publication.share_grant_id = g.id) AND (publication.consent_id = g.consent_id))))
     JOIN public.team_memory_representations r ON (((r.id = publication.representation_id) AND (r.share_grant_id = g.id) AND (r.consent_id = g.consent_id) AND (r.logical_memory_id = g.logical_memory_id) AND (r.team_id = g.team_id) AND (r.team_workspace_id = g.team_workspace_id))))
     JOIN public.logical_memory_source_revision_bindings source_binding ON (((source_binding.source_revision_id = r.source_revision_id) AND (source_binding.logical_memory_id = g.logical_memory_id) AND (source_binding.owner_principal_id = g.owner_principal_id) AND (source_binding.source_kind = g.source_kind))));


