    CONSTRAINT team_memory_semantic_items_hash_check CHECK (((length(content_hash) = 64) AND ((embedding_input_hash IS NULL) OR (length(embedding_input_hash) = 64)))),
    CONSTRAINT team_memory_semantic_items_policy_check CHECK (((representation_policy_revision > 0) AND (content_policy_version > 0) AND (classifier_version > 0))),
    CONSTRAINT team_memory_semantic_items_position_check CHECK (((source_item_index >= 0) AND (encrypted_chunk_index >= 0) AND (encrypted_chunk_item_index >= 0) AND (source_revision >= 0)))
);


