    CONSTRAINT team_memory_sharing_rules_authority_check CHECK (((authority_version > 0) AND (publisher_fence > 0))),
    CONSTRAINT team_memory_sharing_rules_content_labels_check CHECK (((jsonb_typeof(content_privacy_labels) = 'object'::text) AND (content_privacy_labels ?& ARRAY['account_number'::text, 'private_address'::text, 'private_email'::text, 'private_person'::text, 'private_phone'::text, 'private_url'::text, 'private_date'::text, 'secret'::text]) AND ((content_privacy_labels - ARRAY['account_number'::text, 'private_address'::text, 'private_email'::text, 'private_person'::text, 'private_phone'::text, 'private_url'::text, 'private_date'::text, 'secret'::text]) = '{}'::jsonb) AND (jsonb_typeof((content_privacy_labels -> 'account_number'::text)) = 'boolean'::text) AND (jsonb_typeof((content_privacy_labels -> 'private_address'::text)) = 'boolean'::text) AND (jsonb_typeof((content_privacy_labels -> 'private_email'::text)) = 'boolean'::text) AND (jsonb_typeof((content_privacy_labels -> 'private_person'::text)) = 'boolean'::text) AND (jsonb_typeof((content_privacy_labels -> 'private_phone'::text)) = 'boolean'::text) AND (jsonb_typeof((content_privacy_labels -> 'private_url'::text)) = 'boolean'::text) AND (jsonb_typeof((content_privacy_labels -> 'private_date'::text)) = 'boolean'::text) AND (jsonb_typeof((content_privacy_labels -> 'secret'::text)) = 'boolean'::text))),
    CONSTRAINT team_memory_sharing_rules_content_policy_check CHECK ((((content_policy_version = 0) AND (content_privacy_labels = '{"secret": false, "private_url": false, "private_date": false, "private_email": false, "private_phone": false, "account_number": false, "private_person": false, "private_address": false}'::jsonb) AND (approved_global_privacy_policy_hash IS NULL) AND (approved_effective_privacy_labels IS NULL)) OR ((content_policy_version > 0) AND (approved_global_privacy_policy_hash IS NOT NULL) AND (approved_global_privacy_policy_hash ~ '^[a-f0-9]{64}$'::text) AND (approved_effective_privacy_labels IS NOT NULL)))),
    CONSTRAINT team_memory_sharing_rules_fidelity_check CHECK ((maximum_fidelity = ANY (ARRAY['memory_events'::public.shared_memory_representation, 'lcm_leaves'::public.shared_memory_representation, 'lcm_rollups'::public.shared_memory_representation]))),
    CONSTRAINT team_memory_sharing_rules_lifecycle_check CHECK ((((state = ANY (ARRAY['active'::text, 'paused'::text])) AND (stopped_at IS NULL)) OR ((state = 'stopped'::text) AND (stopped_at IS NOT NULL)))),
