    archived_at timestamp with time zone,
    entitlement_status public.team_entitlement_status DEFAULT 'active'::public.team_entitlement_status NOT NULL,
    entitlement_reason text,
    entitlement_updated_at timestamp with time zone,
    created_by_user_id uuid,
    creation_idempotency_key_hash text,
    creation_request_hash text,
    version integer DEFAULT 1 NOT NULL,
    lifecycle public.team_lifecycle DEFAULT 'active'::public.team_lifecycle NOT NULL,
    suspended_at timestamp with time zone,
    deletion_requested_at timestamp with time zone,
    tombstoned_at timestamp with time zone,
    retain_until timestamp with time zone,
    purge_completed_at timestamp with time zone,
    CONSTRAINT teams_creation_idempotency_shape_check CHECK ((((created_by_user_id IS NULL) AND (creation_idempotency_key_hash IS NULL) AND (creation_request_hash IS NULL)) OR ((created_by_user_id IS NOT NULL) AND (length(creation_idempotency_key_hash) = 64) AND (length(creation_request_hash) = 64)))),
    CONSTRAINT teams_lifecycle_shape_check CHECK ((((lifecycle = 'active'::public.team_lifecycle) AND (suspended_at IS NULL) AND (deletion_requested_at IS NULL) AND (tombstoned_at IS NULL) AND (purge_completed_at IS NULL)) OR ((lifecycle = 'suspended'::public.team_lifecycle) AND (suspended_at IS NOT NULL) AND (deletion_requested_at IS NULL) AND (tombstoned_at IS NULL) AND (purge_completed_at IS NULL)) OR ((lifecycle = ANY (ARRAY['deletion_requested'::public.team_lifecycle, 'purge_pending'::public.team_lifecycle])) AND (deletion_requested_at IS NOT NULL) AND (tombstoned_at IS NOT NULL) AND (purge_completed_at IS NULL)) OR ((lifecycle = 'purged'::public.team_lifecycle) AND (deletion_requested_at IS NOT NULL) AND (tombstoned_at IS NOT NULL) AND (purge_completed_at IS NOT NULL)))),
    CONSTRAINT teams_name_check CHECK (((length(TRIM(BOTH FROM name)) > 0) AND (char_length(name) <= 80) AND (name = NORMALIZE(name, NFC)))),
    CONSTRAINT teams_no_archive_check CHECK ((archived_at IS NULL)),
    CONSTRAINT teams_version_check CHECK ((version > 0))
);


